 SELECT * INTO matchrow FROM public."HuroofMatch" WHERE ("namespace","id","roomId")=(p_namespace,st."activeMatchId",p_room) FOR UPDATE;
 IF NOT FOUND OR matchrow."state" NOT IN ('ACTIVE','FINISHED') OR st."privateState"->'room'->'game'->>'lifecycle' IS NULL OR candidate_next->'game'->>'lifecycle' IS NULL THEN RAISE EXCEPTION 'current match unavailable'; END IF;
 IF matchrow."profile"->>'schemaVersion'='huroof-gameplay-profile-v1' AND matchrow."profile"->>'gameKind'='categories' AND NOT EXISTS(SELECT 1 FROM public."HuroofMatchPin" mp WHERE (mp."namespace",mp."matchId")=(matchrow."namespace",matchrow."id") AND (mp."profileRawArtifactId",mp."profileRawArtifactHash")=(matchrow."profileRawArtifactId",matchrow."profileHash") AND mp."config"=matchrow."config" AND (st."privateState"->'room'->'config'-'showQuestionOnAudience')=(matchrow."config"-'showQuestionOnAudience') AND (NOT (st."privateState"->'room'->'config') ? 'showQuestionOnAudience' OR jsonb_typeof(st."privateState"->'room'->'config'->'showQuestionOnAudience')='boolean') AND public.int5b_hash_json(matchrow."config")=matchrow."configHash" AND encode(int4_crypto.digest(matchrow."rawIntent",'sha256'),'hex')=matchrow."rawIntentHash" AND convert_from(matchrow."rawIntent",'UTF8')::JSONB->'request'->'initial'->'config'=matchrow."config" AND convert_from(matchrow."rawIntent",'UTF8')::JSONB->'request'->'initial'->>'configHash'=matchrow."configHash" AND convert_from(matchrow."rawIntent",'UTF8')::JSONB->'resolved'->'config'=matchrow."config" AND convert_from(matchrow."rawIntent",'UTF8')::JSONB->'resolved'->>'configHash'=matchrow."configHash") THEN RAISE EXCEPTION 'category configuration chain unavailable'; END IF;
 IF st."status"='FINISHED' AND (matchrow."state"<>'FINISHED' OR NOT ((p_intent->>'type'='BEGIN_CORRECTION' AND candidate_next->'game'->>'lifecycle'='CORRECTION') OR (p_intent->>'type'='SET_AUDIENCE_QUESTION_VISIBILITY' AND candidate_next->'game'->>'lifecycle'='MATCH_COMPLETE'))) THEN RAISE EXCEPTION 'terminal command unavailable'; END IF;
 IF st."status"='ACTIVE' AND matchrow."state"<>'ACTIVE' THEN RAISE EXCEPTION 'match state mismatch'; END IF;
 IF st."status" NOT IN ('ACTIVE','FINISHED') THEN RAISE EXCEPTION 'current match unavailable'; END IF;
 -- Build private challenge authority from the locked canonical roster and current membership rows.
 IF p_intent->>'type' LIKE 'CHALLENGE_%' OR p_intent->>'type'='SERVER_CHALLENGE_DEADLINE' THEN
  SELECT i."firebaseUid" INTO host_uid FROM public."FirebaseIdentity" i JOIN public."HuroofMember" m ON m."firebaseIdentityId"=i."id" WHERE (m."namespace",m."roomId",m."firebaseIdentityId")=(p_namespace,p_room,room."ownerFirebaseIdentityId") AND m."revokedAt" IS NULL AND m."role"='OWNER' AND i."firebaseProjectId"=project;
  IF NOT FOUND OR host_uid IS NULL OR host_uid='' OR jsonb_typeof(COALESCE(st."privateState"->'room'->'manualParticipants','[]'::JSONB)) IS DISTINCT FROM 'array' OR (SELECT count(*) FROM jsonb_array_elements(p_members) x(value) WHERE x.value->'active'='true'::JSONB)<>(SELECT count(*) FROM public."HuroofMember" m WHERE (m."namespace",m."roomId")=(p_namespace,p_room) AND m."revokedAt" IS NULL) OR (SELECT count(DISTINCT x.value->>'uid') FROM jsonb_array_elements(p_members) x(value) WHERE x.value->'active'='true'::JSONB)<>(SELECT count(*) FROM jsonb_array_elements(p_members) x(value) WHERE x.value->'active'='true'::JSONB) OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_members) x(value) WHERE x.value->'active'='true'::JSONB AND (jsonb_typeof(x.value->'uid') IS DISTINCT FROM 'string' OR x.value->>'role' NOT IN ('host','player','audience') OR (x.value->>'role'='player' AND (x.value->>'team' IS NULL OR x.value->>'team' NOT IN ('horizontal','vertical'))) OR NOT EXISTS(SELECT 1 FROM public."HuroofMember" m JOIN public."FirebaseIdentity" i ON i."id"=m."firebaseIdentityId" WHERE (m."namespace",m."roomId")=(p_namespace,p_room) AND m."revokedAt" IS NULL AND i."firebaseProjectId"=project AND i."firebaseUid"=x.value->>'uid' AND ((x.value->>'role'='host' AND m."role"='OWNER' AND i."firebaseUid"=host_uid) OR (x.value->>'role' IN ('player','audience') AND m."role"='MEMBER'))))) THEN RAISE EXCEPTION 'challenge roster unavailable'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(COALESCE(st."privateState"->'room'->'manualParticipants','[]'::JSONB)))<>(SELECT count(*) FROM public."HuroofParticipant" pp WHERE (pp."namespace",pp."roomId")=(p_namespace,p_room) AND pp."memberFirebaseIdentityId" IS NULL) OR (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(COALESCE(st."privateState"->'room'->'manualParticipants','[]'::JSONB)))<>(SELECT count(*) FROM jsonb_array_elements(COALESCE(st."privateState"->'room'->'manualParticipants','[]'::JSONB))) OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(st."privateState"->'room'->'manualParticipants','[]'::JSONB)) x(value) WHERE jsonb_typeof(x.value->'id') IS DISTINCT FROM 'string' OR x.value->>'team' IS NULL OR x.value->>'team' NOT IN ('horizontal','vertical') OR NOT EXISTS(SELECT 1 FROM public."HuroofParticipant" pp WHERE (pp."namespace",pp."roomId",pp."id")=(p_namespace,p_room,x.value->>'id') AND pp."memberFirebaseIdentityId" IS NULL AND pp."team"=x.value->>'team' AND pp."displayName"=x.value->>'displayName')) THEN RAISE EXCEPTION 'challenge roster unavailable'; END IF;
  SELECT COALESCE(jsonb_agg(v),'[]'::JSONB) INTO challenge_people FROM (
   SELECT jsonb_build_object('kind','member','id','member:'||(x.value->>'uid'),'actorUid',x.value->>'uid','team',x.value->>'team') v FROM jsonb_array_elements(p_members) x(value) WHERE x.value->'active'='true'::JSONB AND x.value->>'role'='player'
   UNION ALL SELECT jsonb_build_object('kind','manual','id','manual:'||(x.value->>'id'),'controllerUid',host_uid,'team',x.value->>'team') FROM jsonb_array_elements(COALESCE(st."privateState"->'room'->'manualParticipants','[]'::JSONB)) x(value)
  ) participants;
  challenge_context:=jsonb_build_object('hostUid',host_uid,'participants',challenge_people,'assignmentBase',(st."privateState"->'room'->>'activeQuestionOccurrence')||':'||st."revision"::TEXT,'protocolHash',st."privateState"->'room'->'config'->'challenge'->>'protocolVersion','stimulusHash',st."privateState"->'room'->'challenge'->>'definitionHash');
 END IF;
 -- Rejoin immutable definition and derive every bridge-owned state/game/result delta before effects.
 IF p_intent->>'type' LIKE 'CHALLENGE_%' OR p_intent->>'type'='SERVER_CHALLENGE_DEADLINE' THEN
  challenge_definition:=public.pro273_r1_definition(p_namespace,p_room,st."activeMatchId");
  IF NOT public.pro273_r1_nonaward(challenge_definition,st."privateState"->'room'->'challenge',candidate_next->'challenge',p_intent,challenge_context,actor_uid,challenge_now) THEN RAISE EXCEPTION 'challenge transition unavailable'; END IF;
  IF (candidate_next-ARRAY['revision','challenge','challengeBridge','game']::TEXT[]) IS DISTINCT FROM (st."privateState"->'room'-ARRAY['revision','challenge','challengeBridge','game']::TEXT[]) THEN RAISE EXCEPTION 'challenge transition unavailable'; END IF;
  old_applied:=prior_bridge->'applied';new_applied:=next_bridge->'applied';
  IF (CASE WHEN NOT prior_bridge ? 'appliedEncoding' THEN prior_bridge||jsonb_build_object('appliedEncoding','utf8-hex-v1') ELSE prior_bridge END)-'applied' IS DISTINCT FROM next_bridge-'applied' THEN RAISE EXCEPTION 'challenge transition unavailable'; END IF;
  IF old_applied IS NOT DISTINCT FROM new_applied THEN expected_game:=st."privateState"->'room'->'game';
  ELSE
   next_team:=candidate_next->'challenge'->>'answeringTeam';
   IF next_team NOT IN ('horizontal','vertical') OR next_team IS NULL OR (st."privateState"->'room'->'game'->>'answeringTeam' IS DISTINCT FROM next_team AND (candidate_next->'challenge'->>'attempt' IS DISTINCT FROM 'steal' OR st."privateState"->'room'->'game'->>'answeringTeam' IS DISTINCT FROM st."privateState"->'room'->'challenge'->>'entitledTeam' OR st."privateState"->'room'->'game'->>'attempt' IS DISTINCT FROM 'initial')) THEN RAISE EXCEPTION 'challenge transition unavailable'; END IF;
   IF new_applied->>active_key='award' THEN
    expected_path:=public.pro273_r1_path(candidate_next->'game'->'board',next_team);
    expected_game:=public.pro273_r1_game(st."privateState"->'room'->'game',expected_path,next_team,'award');
   ELSIF new_applied->>active_key='continue' THEN expected_game:=public.pro273_r1_game(st."privateState"->'room'->'game',NULL,next_team,'continue');
   ELSE RAISE EXCEPTION 'challenge transition unavailable'; END IF;
  END IF;
  IF candidate_next->'game' IS DISTINCT FROM expected_game OR NOT public.pro273_r1_semantic(expected_game,p_semantic) THEN RAISE EXCEPTION 'challenge result unavailable'; END IF;
 END IF;
 normalized_next:=candidate_next;
 -- Exact current policy and historical immutable subject are rejoined after room/state locks.
 IF (p_intent->>'type' IN ('SELECT_CELL','LETTER_REVEALED','RETRY_CELL','RETURN_CELL','START_NEXT_ROUND') OR (p_intent->>'type'='CHALLENGE_CONTINUE' AND st."privateState"->'room'->'config'->>'gameKind'='categories' AND st."privateState"->'room'->'challenge'->>'result' IN ('failed','void'))) AND p_custody IS NULL THEN RAISE EXCEPTION 'custody evidence unavailable'; END IF;
 IF p_custody IS NOT NULL THEN PERFORM public.eng03_03_custody_assert(p_namespace,project,p_identity,p_room,p_generation,NULL,matchrow."id",p_policy_revision,p_policy_hash,p_custody); END IF;
 terminal:=normalized_next->'game'->>'lifecycle'='MATCH_COMPLETE';
 IF jsonb_typeof(p_semantic) IS DISTINCT FROM 'object' OR p_semantic->'board' IS DISTINCT FROM normalized_next->'game'->'board' OR p_semantic->'questionScores' IS DISTINCT FROM normalized_next->'game'->'questionScores' OR p_semantic->'roundOutcomeHistory' IS DISTINCT FROM normalized_next->'game'->'roundOutcomeHistory' OR p_semantic->'currentRound' IS DISTINCT FROM normalized_next->'game'->'currentRound' OR p_semantic->'endedWithoutWinner' IS DISTINCT FROM COALESCE(normalized_next->'game'->'endedWithoutWinner','false'::JSONB) THEN RAISE EXCEPTION 'result semantics mismatch'; END IF;
 SELECT * INTO latest FROM public."HuroofMatchResult" WHERE "namespace"=p_namespace AND "matchId"=matchrow."id" ORDER BY "resultVersion" DESC LIMIT 1;
 last_ref:=st."privateState"->'lastResult';
 IF last_ref='null'::JSONB THEN last_ref:=NULL; END IF;
 IF FOUND THEN
  IF jsonb_typeof(last_ref) IS DISTINCT FROM 'object' OR last_ref->>'version' IS DISTINCT FROM latest."resultVersion"::TEXT OR last_ref->>'hash' IS DISTINCT FROM latest."resultHash" THEN RAISE EXCEPTION 'latest result reference mismatch'; END IF;
 ELSE
  IF last_ref IS NOT NULL AND last_ref<>'null'::JSONB THEN RAISE EXCEPTION 'unexpected result reference'; END IF;
 END IF;
 IF st."status"='FINISHED' AND (st."privateState"->'currentResult' IS DISTINCT FROM last_ref OR last_ref IS NULL OR (p_intent->>'type'='BEGIN_CORRECTION' AND EXISTS(SELECT 1 FROM public."HuroofRematchLink" child WHERE child."namespace"=p_namespace AND child."predecessorMatchId"=matchrow."id"))) THEN RAISE EXCEPTION 'correction on superseded result'; END IF;
 changed:=terminal AND (last_ref IS NULL OR st."privateState"->'previousTerminalSemantic' IS DISTINCT FROM p_semantic);
 IF st."status"='FINISHED' AND p_intent->>'type'='SET_AUDIENCE_QUESTION_VISIBILITY' AND changed THEN RAISE EXCEPTION 'terminal result cannot change during visibility command'; END IF;
 event_type:=CASE WHEN changed THEN 'FINISHED' ELSE p_intent->>'type' END;
 next_status:=CASE WHEN terminal THEN 'FINISHED' ELSE 'ACTIVE' END;
 -- Normalize only the two reviewed projection timing paths after nontiming validation and before writes.
 IF challenge_now IS NOT NULL THEN
  time_stamp:=timestamp '1970-01-01 00:00:00'+make_interval(days=>(challenge_now/86400000)::INTEGER,secs=>((challenge_now%86400000)/1000)::DOUBLE PRECISION)+(challenge_now%1000)*interval '1 millisecond';
  year_no:=extract(year FROM time_stamp)::INTEGER;
  time_iso:=CASE WHEN year_no<10000 THEN lpad(year_no::TEXT,4,'0') ELSE '+'||lpad(year_no::TEXT,6,'0') END||to_char(time_stamp,'-MM-DD"T"HH24:MI:SS')||'.'||lpad((challenge_now%1000)::TEXT,3,'0')||'Z';
  deadline_iso:=NULL;
  IF normalized_next->'challenge' ? 'deadlineAt' THEN
   IF jsonb_typeof(normalized_next->'challenge'->'deadlineAt') IS DISTINCT FROM 'number' OR normalized_next->'challenge'->>'deadlineAt' !~ '^(0|[1-9][0-9]{0,15})$' OR (normalized_next->'challenge'->>'deadlineAt')::NUMERIC>8640000000000000 THEN RAISE EXCEPTION 'challenge time unavailable'; END IF;
   deadline_ms:=(normalized_next->'challenge'->>'deadlineAt')::BIGINT;
   time_stamp:=timestamp '1970-01-01 00:00:00'+make_interval(days=>(deadline_ms/86400000)::INTEGER,secs=>((deadline_ms%86400000)/1000)::DOUBLE PRECISION)+(deadline_ms%1000)*interval '1 millisecond';
   year_no:=extract(year FROM time_stamp)::INTEGER;
   deadline_iso:=CASE WHEN year_no<10000 THEN lpad(year_no::TEXT,4,'0') ELSE '+'||lpad(year_no::TEXT,6,'0') END||to_char(time_stamp,'-MM-DD"T"HH24:MI:SS')||'.'||lpad((deadline_ms%1000)::TEXT,3,'0')||'Z';
  END IF;
  closed_room:=CASE jsonb_typeof(normalized_next->'closedAt') WHEN 'boolean' THEN normalized_next->'closedAt'='true'::JSONB WHEN 'number' THEN (normalized_next->>'closedAt')::NUMERIC<>0 WHEN 'string' THEN normalized_next->>'closedAt'<>'' WHEN 'object' THEN true WHEN 'array' THEN true ELSE false END;
  normalized_projections:='[]'::JSONB;
  FOR item IN SELECT value FROM jsonb_array_elements(p_projections) LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(item->'uid') IS DISTINCT FROM 'string' OR jsonb_typeof(item->'payload') IS DISTINCT FROM 'object' OR jsonb_typeof(item->'payload'->'serverTime') IS DISTINCT FROM 'string' OR item->'payload'->>'serverTime' !~ '^(\+[0-9]{6}|[0-9]{4})-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' OR jsonb_typeof(item->'payload'->'projection') IS DISTINCT FROM 'object' OR item->'payload'->>'roomId' IS DISTINCT FROM p_room OR item->'payload'->>'revision' IS DISTINCT FROM normalized_next->>'revision' THEN RAISE EXCEPTION 'challenge projection unavailable'; END IF;
   SELECT x.value->>'role',x.value->>'team' INTO projection_role,member_team FROM jsonb_array_elements(p_members) x(value) WHERE x.value->'active'='true'::JSONB AND x.value->>'uid'=item->>'uid';
   IF NOT FOUND OR projection_role NOT IN ('host','player','audience') OR item->'payload'->>'role' IS DISTINCT FROM projection_role THEN RAISE EXCEPTION 'challenge projection unavailable'; END IF;
   expected_recipient:=projection_role;expected_team:=NULL;
   IF projection_role='player' THEN
    expected_recipient:=CASE WHEN normalized_next->'challenge'->'assignments'->>'guide'='member:'||(item->>'uid') THEN 'guide' WHEN normalized_next->'challenge'->'assignments'->>'mover'='member:'||(item->>'uid') THEN 'mover' WHEN normalized_next->'challenge'->'assignments'->>'captain'='member:'||(item->>'uid') THEN 'captain' WHEN normalized_next->'challenge'->'assignments'->>'stealCaptain'='member:'||(item->>'uid') THEN 'stealCaptain' ELSE 'waiting' END;
    IF expected_recipient IN ('guide','mover','captain') THEN expected_team:=normalized_next->'challenge'->>'entitledTeam'; ELSIF expected_recipient='stealCaptain' THEN expected_team:=CASE normalized_next->'challenge'->>'entitledTeam' WHEN 'horizontal' THEN 'vertical' WHEN 'vertical' THEN 'horizontal' ELSE NULL END; END IF;
   END IF;
   expected_challenge:=jsonb_typeof(normalized_next->'challenge')='object' AND normalized_next->'challenge'->'continued' IS DISTINCT FROM 'true'::JSONB AND NOT closed_room AND (projection_role<>'player' OR expected_team IS NULL OR member_team=expected_team);
   proposed_challenge:=item->'payload'->'projection'->'challenge';
   IF expected_challenge THEN
    IF jsonb_typeof(proposed_challenge) IS DISTINCT FROM 'object' OR proposed_challenge->>'recipient' IS DISTINCT FROM expected_recipient OR proposed_challenge->'occurrence' IS DISTINCT FROM normalized_next->'challenge'->'occurrence' OR proposed_challenge->'revision' IS DISTINCT FROM normalized_next->'challenge'->'revision' OR proposed_challenge->'stage' IS DISTINCT FROM normalized_next->'challenge'->'stage' OR proposed_challenge->'assignmentGeneration' IS DISTINCT FROM normalized_next->'challenge'->'assignmentGeneration' OR proposed_challenge->'entitledTeam' IS DISTINCT FROM normalized_next->'challenge'->'entitledTeam' OR proposed_challenge->'answeringTeam' IS DISTINCT FROM normalized_next->'challenge'->'answeringTeam' OR proposed_challenge->'strikes' IS DISTINCT FROM normalized_next->'challenge'->'strikes' OR proposed_challenge->'assignments' IS DISTINCT FROM normalized_next->'challenge'->'assignments' OR proposed_challenge->'attemptsClosed' IS DISTINCT FROM normalized_next->'challenge'->'attemptsClosed' OR proposed_challenge->'solutionRevealed' IS DISTINCT FROM normalized_next->'challenge'->'solutionRevealed' OR proposed_challenge->'result' IS DISTINCT FROM normalized_next->'challenge'->'result' OR proposed_challenge->'disclosureGeneration' IS DISTINCT FROM normalized_next->'challenge'->'disclosureGeneration' OR proposed_challenge->'paused' IS DISTINCT FROM to_jsonb((normalized_next->'challenge') ? 'paused') OR (proposed_challenge ? 'deadlineAt' AND (jsonb_typeof(proposed_challenge->'deadlineAt') IS DISTINCT FROM 'string' OR proposed_challenge->>'deadlineAt' !~ '^(\+[0-9]{6}|[0-9]{4})-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$')) THEN RAISE EXCEPTION 'challenge projection unavailable'; END IF;
    IF deadline_iso IS NULL THEN norm_item:=jsonb_set(item,'{payload,projection,challenge}',proposed_challenge-'deadlineAt'); ELSE norm_item:=jsonb_set(item,'{payload,projection,challenge,deadlineAt}',to_jsonb(deadline_iso),true); END IF;
   ELSE
    IF (item->'payload'->'projection') ? 'challenge' THEN RAISE EXCEPTION 'challenge projection unavailable'; END IF; norm_item:=item;
   END IF;
   norm_item:=jsonb_set(norm_item,'{payload,serverTime}',to_jsonb(time_iso));
   IF NOT public.eng03_03_projection_safe(norm_item->'payload',projection_role='host') THEN RAISE EXCEPTION 'challenge projection unavailable'; END IF;
   normalized_projections:=normalized_projections||jsonb_build_array(norm_item);
  END LOOP;
 END IF;
 next_private:=st."privateState"||jsonb_build_object('room',normalized_next,'members',p_members,'currentResult',CASE WHEN terminal AND NOT changed THEN last_ref ELSE 'null'::JSONB END);
 IF jsonb_array_length(normalized_projections)<>(SELECT count(*) FROM public."HuroofMember" m WHERE m."namespace"=p_namespace AND m."roomId"=p_room AND m."revokedAt" IS NULL) OR (SELECT count(DISTINCT value->>'uid') FROM jsonb_array_elements(normalized_projections))<>jsonb_array_length(normalized_projections) THEN RAISE EXCEPTION 'projection scope mismatch'; END IF;
 seq:=st."sequence"+1; rev:=st."revision"+1;
 event_id:=encode(int4_crypto.digest(convert_to(jsonb_build_array(p_namespace,p_room,p_identity,p_intent->>'intentId')::TEXT,'UTF8'),'sha256'),'hex');
 intent_bytes:=convert_to(p_intent::TEXT,'UTF8'); outcome:=jsonb_build_object('revision',rev,'sequence',seq,'replayed',false); outcome_bytes:=convert_to(outcome::TEXT,'UTF8');
 INSERT INTO public."HuroofCommandReceipt"("namespace","roomId","actorFirebaseIdentityId","requestKey","matchId","intent","intentHash","outcome","outcomeHash","resultingRevision","resultingSequence") VALUES(p_namespace,p_room,p_identity,p_intent->>'intentId',st."activeMatchId",intent_bytes,encode(int4_crypto.digest(intent_bytes,'sha256'),'hex'),outcome_bytes,encode(int4_crypto.digest(outcome_bytes,'sha256'),'hex'),rev,seq);
 INSERT INTO public."HuroofEvent"("namespace","roomId","sequence","id","matchId","actorFirebaseIdentityId","requestKey","revision","eventType") VALUES(p_namespace,p_room,seq,event_id,st."activeMatchId",p_identity,p_intent->>'intentId',rev,event_type);
 -- The exact receipt/event exists before the match guard validates a terminal reopening.
 IF st."status"='FINISHED' AND p_intent->>'type'='BEGIN_CORRECTION' THEN UPDATE public."HuroofMatch" SET "state"='ACTIVE',"version"="version"+1 WHERE ("namespace","id")=(p_namespace,matchrow."id"); END IF;
 IF terminal AND matchrow."state"='ACTIVE' THEN UPDATE public."HuroofMatch" SET "state"='FINISHED',"version"="version"+1 WHERE ("namespace","id")=(p_namespace,matchrow."id"); END IF;
 IF changed THEN
  result_version:=CASE WHEN last_ref IS NULL THEN 1 ELSE (last_ref->>'version')::BIGINT+1 END;
  result_bytes:=convert_to(p_semantic::TEXT,'UTF8'); result_hash:=encode(int4_crypto.digest(result_bytes,'sha256'),'hex');
  result_id:=encode(int4_crypto.digest(convert_to(jsonb_build_array(p_namespace,matchrow."id",seq,'result')::TEXT,'UTF8'),'sha256'),'hex');
  provenance_bytes:=convert_to(jsonb_build_object('schema','huroof-command-result-v1','namespace',p_namespace,'roomId',p_room,'matchId',matchrow."id",'admissionId',matchrow."admissionId",'eventId',event_id,'revision',rev,'sequence',seq,'intentHash',encode(int4_crypto.digest(intent_bytes,'sha256'),'hex'))::TEXT,'UTF8');
  INSERT INTO public."HuroofRawArtifact"("namespace","id","contentHash","byteLength","mediaType","rawBytes","provenanceBytes","provenanceHash","serialization") VALUES(p_namespace,result_id,result_hash,octet_length(result_bytes),'application/json',result_bytes,provenance_bytes,encode(int4_crypto.digest(provenance_bytes,'sha256'),'hex'),'huroof-command-result-v1');
  INSERT INTO public."HuroofMatchResult"("namespace","matchId","roomId","resultVersion","resultHash","ownerFirebaseIdentityId","admissionId","terminalEventId","terminalSequence","rawArtifactId","previousVersion","previousHash") VALUES(p_namespace,matchrow."id",p_room,result_version,result_hash,room."ownerFirebaseIdentityId",matchrow."admissionId",event_id,seq,result_id,CASE WHEN last_ref IS NULL THEN NULL ELSE (last_ref->>'version')::BIGINT END,CASE WHEN last_ref IS NULL THEN NULL ELSE last_ref->>'hash' END);
  INSERT INTO public."HuroofOwnerHistoryHead"("namespace","ownerFirebaseIdentityId") VALUES(p_namespace,room."ownerFirebaseIdentityId") ON CONFLICT("namespace","ownerFirebaseIdentityId") DO NOTHING;
  PERFORM public.eng03_03_lock_history(p_namespace,room."ownerFirebaseIdentityId");
  SELECT * INTO history FROM public."HuroofOwnerHistoryHead" WHERE ("namespace","ownerFirebaseIdentityId")=(p_namespace,room."ownerFirebaseIdentityId");
  INSERT INTO public."HuroofOwnerHistoryEntry"("namespace","ownerFirebaseIdentityId","sequence","matchId","resultVersion","resultHash","occurredAt","provenance","provenanceHash") VALUES(p_namespace,room."ownerFirebaseIdentityId",history."nextSequence",matchrow."id",result_version,result_hash,clock_timestamp(),provenance_bytes,encode(int4_crypto.digest(provenance_bytes,'sha256'),'hex'));
  last_ref:=jsonb_build_object('version',result_version,'hash',result_hash);
  next_private:=next_private||jsonb_build_object('lastResult',last_ref,'currentResult',last_ref,'previousTerminalRoom',normalized_next,'previousTerminalSemantic',p_semantic);
 END IF;
 UPDATE public."HuroofCanonicalState" SET "status"=next_status,"revision"=rev,"sequence"=seq,"privateState"=next_private,"updatedAt"=clock_timestamp() WHERE ("namespace","roomId")=(p_namespace,p_room);
 FOR item IN SELECT value FROM jsonb_array_elements(normalized_projections) LOOP
  SELECT i."id" INTO subject_identity FROM public."FirebaseIdentity" i JOIN public."HuroofMember" m ON m."firebaseIdentityId"=i."id" AND m."namespace"=p_namespace AND m."roomId"=p_room AND m."revokedAt" IS NULL WHERE i."firebaseProjectId"=project AND i."firebaseUid"=item->>'uid';
  IF NOT FOUND THEN RAISE EXCEPTION 'projection scope invalid'; END IF;
  SELECT x.value->>'role' INTO subject_role FROM jsonb_array_elements(p_members) AS x(value) WHERE x.value->>'uid'=item->>'uid' AND x.value->'active'='true'::JSONB;
  IF NOT FOUND OR subject_role NOT IN ('host','player','audience') OR item->'payload'->>'role' IS DISTINCT FROM subject_role OR item->'payload'->>'revision' IS DISTINCT FROM rev::TEXT OR NOT public.eng03_03_projection_safe(item->'payload',subject_identity=room."ownerFirebaseIdentityId") THEN RAISE EXCEPTION 'projection scope invalid'; END IF;
  INSERT INTO public."HuroofProjection"("namespace","roomId","audience","scope","revision","throughSequence","authGeneration","payload") VALUES(p_namespace,p_room,CASE WHEN subject_identity=room."ownerFirebaseIdentityId" THEN 'OWNER' ELSE 'MEMBER' END,subject_identity,rev,seq,room."generation",item->'payload') ON CONFLICT("namespace","roomId","audience","scope") DO UPDATE SET "revision"=EXCLUDED."revision","throughSequence"=EXCLUDED."throughSequence","authGeneration"=EXCLUDED."authGeneration","payload"=EXCLUDED."payload","updatedAt"=clock_timestamp();
 END LOOP;
 INSERT INTO public."HuroofProjection"("namespace","roomId","audience","scope","revision","throughSequence","authGeneration","payload") VALUES(p_namespace,p_room,'PUBLIC','public',rev,seq,room."generation",jsonb_build_object('status',normalized_next->'game'->>'lifecycle','revision',rev)) ON CONFLICT("namespace","roomId","audience","scope") DO UPDATE SET "revision"=EXCLUDED."revision","throughSequence"=EXCLUDED."throughSequence","authGeneration"=EXCLUDED."authGeneration","payload"=EXCLUDED."payload","updatedAt"=clock_timestamp();
 INSERT INTO public."HuroofRealtimeOutbox"("namespace","roomId","sequence","eventId") VALUES(p_namespace,p_room,seq,event_id);
 INSERT INTO public."HuroofOutboxDelivery"("namespace","roomId","sequence") VALUES(p_namespace,p_room,seq);
 RETURN outcome;
END $$;

CREATE OR REPLACE FUNCTION public.eng03_03_projection_safe(p_value JSONB,p_host BOOLEAN) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE item RECORD; element RECORD; field RECORD; list_key TEXT; list_fields TEXT[]; challenge JSONB; stimulus JSONB; allowed_stimulus TEXT[]; allowed_reveal TEXT[];
BEGIN
 IF p_value IS NULL OR public.eng03_02_has_secret_key(p_value) THEN RETURN FALSE; END IF;
 IF jsonb_typeof(p_value)='object' THEN
  IF p_value ? 'role' AND jsonb_typeof(p_value->'projection'->'challenge')='object' AND ((p_value->>'role'='host' AND (NOT p_host OR p_value->'projection'->'challenge'->>'recipient' IS DISTINCT FROM 'host')) OR (p_value->>'role'='audience' AND (p_host OR p_value->'projection'->'challenge'->>'recipient' IS DISTINCT FROM 'audience')) OR (p_value->>'role'='player' AND (p_host OR p_value->'projection'->'challenge'->>'recipient' NOT IN ('waiting','guide','mover','captain','stealCaptain'))) OR p_value->>'role' NOT IN ('host','player','audience')) THEN RETURN FALSE; END IF;
  IF p_value ? 'challenge' THEN
   challenge:=p_value->'challenge';
   IF jsonb_typeof(challenge) IS DISTINCT FROM 'object' OR (challenge-ARRAY['protocolVersion','kind','recipient','occurrence','revision','assignmentGeneration','disclosureGeneration','stage','entitledTeam','answeringTeam','paused','strikes','readiness','assignments','readinessSummary','legalActions','timing','deadlineAt','result','attemptsClosed','solutionRevealed','stimulus']::TEXT[])<>'{}'::JSONB OR challenge->>'protocolVersion' IS DISTINCT FROM 't36-challenge-runtime-v1' OR challenge->>'kind' IS NULL OR challenge->>'kind' NOT IN ('navigation','missing_tile','memory','qatar_map','word_search') OR challenge->>'stage' IS NULL OR challenge->>'stage' NOT IN ('setup','countdown','observation','answer','steal_offer','steal','result','void') OR challenge->>'recipient' IS NULL OR (p_host AND challenge->>'recipient' IS DISTINCT FROM 'host') OR (NOT p_host AND challenge->>'recipient' NOT IN ('audience','waiting','guide','mover','captain','stealCaptain')) OR jsonb_typeof(challenge->'paused') IS DISTINCT FROM 'boolean' OR jsonb_typeof(challenge->'attemptsClosed') IS DISTINCT FROM 'boolean' OR jsonb_typeof(challenge->'solutionRevealed') IS DISTINCT FROM 'boolean' OR (challenge->'solutionRevealed'='true'::JSONB AND challenge->'attemptsClosed' IS DISTINCT FROM 'true'::JSONB) OR (NOT p_host AND challenge ? 'readinessSummary') THEN RETURN FALSE; END IF;
   IF NOT challenge ?& ARRAY['occurrence','revision','assignmentGeneration','disclosureGeneration','entitledTeam','answeringTeam','strikes','readiness','assignments','legalActions','timing'] OR jsonb_typeof(challenge->'occurrence') IS DISTINCT FROM 'string' OR challenge->>'occurrence'='' OR jsonb_typeof(challenge->'entitledTeam') IS DISTINCT FROM 'string' OR challenge->>'entitledTeam' NOT IN ('horizontal','vertical') OR jsonb_typeof(challenge->'answeringTeam') IS DISTINCT FROM 'string' OR challenge->>'answeringTeam' NOT IN ('horizontal','vertical') OR EXISTS(SELECT 1 FROM unnest(ARRAY['revision','assignmentGeneration','disclosureGeneration','strikes']) k WHERE jsonb_typeof(challenge->k) IS DISTINCT FROM 'number' OR challenge->>k !~ '^(0|[1-9][0-9]{0,15})$') OR jsonb_typeof(challenge->'readiness') IS DISTINCT FROM 'object' OR ((challenge->'readiness')-ARRAY['protocolHash','assignmentHash','stimulusHash','required','acknowledged']::TEXT[])<>'{}'::JSONB OR NOT (challenge->'readiness') ?& ARRAY['protocolHash','assignmentHash','stimulusHash','required','acknowledged'] OR jsonb_typeof(challenge->'readiness'->'required') IS DISTINCT FROM 'boolean' OR jsonb_typeof(challenge->'readiness'->'acknowledged') IS DISTINCT FROM 'boolean' OR jsonb_typeof(challenge->'assignments') IS DISTINCT FROM 'object' OR ((challenge->'assignments')-ARRAY['guide','mover','captain','stealCaptain']::TEXT[])<>'{}'::JSONB OR jsonb_typeof(challenge->'timing') IS DISTINCT FROM 'object' OR ((challenge->'timing')-ARRAY['countdownSeconds','answerSeconds','observationSeconds']::TEXT[])<>'{}'::JSONB OR jsonb_typeof(challenge->'legalActions') IS DISTINCT FROM 'array' OR (challenge->>'recipient'='audience' AND jsonb_array_length(challenge->'legalActions')<>0) THEN RETURN FALSE; END IF;
   IF (challenge ? 'result' AND (jsonb_typeof(challenge->'result') IS DISTINCT FROM 'string' OR challenge->>'result' NOT IN ('correct','failed','void'))) OR (challenge ? 'deadlineAt' AND jsonb_typeof(challenge->'deadlineAt') IS DISTINCT FROM 'string') THEN RETURN FALSE; END IF;
   IF EXISTS(SELECT 1 FROM unnest(ARRAY['protocolHash','assignmentHash','stimulusHash']) k WHERE jsonb_typeof(challenge->'readiness'->k) IS DISTINCT FROM 'string' OR challenge->'readiness'->>k='') OR EXISTS(SELECT 1 FROM jsonb_each(challenge->'assignments') e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string' OR e.value#>>'{}'='') OR jsonb_typeof(challenge->'timing'->'countdownSeconds') IS DISTINCT FROM 'number' OR challenge->'timing'->>'countdownSeconds' !~ '^(0|[1-9][0-9]{0,15})$' OR EXISTS(SELECT 1 FROM jsonb_each(challenge->'timing') e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'number' OR e.value#>>'{}' !~ '^(0|[1-9][0-9]{0,15})$') OR EXISTS(SELECT 1 FROM jsonb_array_elements(challenge->'legalActions') a WHERE jsonb_typeof(a) IS DISTINCT FROM 'string') THEN RETURN FALSE; END IF;
   IF challenge ? 'readinessSummary' THEN IF jsonb_typeof(challenge->'readinessSummary') IS DISTINCT FROM 'array' OR jsonb_array_length(challenge->'readinessSummary')>217 THEN RETURN FALSE; END IF; FOR element IN SELECT value FROM jsonb_array_elements(challenge->'readinessSummary') LOOP IF jsonb_typeof(element.value) IS DISTINCT FROM 'object' OR (element.value-ARRAY['participantId','acknowledged']::TEXT[])<>'{}'::JSONB OR NOT element.value ?& ARRAY['participantId','acknowledged'] OR jsonb_typeof(element.value->'participantId') IS DISTINCT FROM 'string' OR jsonb_typeof(element.value->'acknowledged') IS DISTINCT FROM 'boolean' THEN RETURN FALSE; END IF; END LOOP; END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(challenge->'legalActions') a(action) WHERE NOT (CASE WHEN p_host THEN CASE WHEN challenge->'attemptsClosed'='true'::JSONB THEN a.action IN ('REVEAL','CONTINUE') WHEN challenge->'paused'='true'::JSONB THEN a.action IN ('RESUME','VOID') WHEN challenge->>'stage'='setup' THEN a.action IN ('ASSIGN','READY','START') WHEN challenge->>'stage'='steal_offer' THEN a.action IN ('START_STEAL','DECLINE_STEAL','VOID') WHEN challenge->>'stage'='answer' THEN a.action IN ('PAUSE','VOID') OR (a.action='MOVE' AND challenge->'assignments'->>'mover' LIKE 'manual:%') OR (a.action='SUBMIT' AND challenge->'assignments'->>'captain' LIKE 'manual:%') WHEN challenge->>'stage'='steal' THEN a.action IN ('PAUSE','VOID') OR (a.action='SUBMIT' AND challenge->'assignments'->>'stealCaptain' LIKE 'manual:%') ELSE a.action IN ('PAUSE','VOID') END ELSE (challenge->>'stage'='setup' AND challenge->>'recipient' NOT IN ('audience','waiting') AND a.action='READY') OR (challenge->>'stage'='answer' AND challenge->>'recipient'='mover' AND a.action='MOVE') OR (((challenge->>'stage'='answer' AND challenge->>'recipient'='captain') OR (challenge->>'stage'='steal' AND challenge->>'recipient'='stealCaptain')) AND a.action='SUBMIT') END)) THEN RETURN FALSE; END IF;
   IF challenge ? 'stimulus' THEN
    stimulus:=challenge->'stimulus';
    IF jsonb_typeof(stimulus) IS DISTINCT FROM 'object' THEN RETURN FALSE; END IF;
    allowed_stimulus:=CASE challenge->>'kind' WHEN 'navigation' THEN CASE WHEN challenge->>'recipient'='guide' THEN ARRAY['rows','columns','start','goal','blocked','current','reveal'] ELSE ARRAY['rows','columns','start','current','confirmedEdges','reveal'] END WHEN 'missing_tile' THEN ARRAY['rows','columns','cells','options','rule','promptAr','reveal'] WHEN 'memory' THEN ARRAY['rows','columns','palette','showSeconds','answerSeconds','instructionAr','cells','promptAr','answerSlots','reveal'] WHEN 'qatar_map' THEN ARRAY['mode','markers','optionIds','promptAr','namedPoints','reveal'] WHEN 'word_search' THEN ARRAY['rows','columns','grid','clueAr','reveal'] ELSE ARRAY[]::TEXT[] END;
    allowed_reveal:=CASE challenge->>'kind' WHEN 'navigation' THEN ARRAY['directions'] WHEN 'missing_tile' THEN ARRAY['correctOptionId'] WHEN 'memory' THEN ARRAY['answers'] WHEN 'qatar_map' THEN ARRAY['answerIds'] WHEN 'word_search' THEN ARRAY['paths'] ELSE ARRAY[]::TEXT[] END;
    IF (stimulus-allowed_stimulus)<>'{}'::JSONB OR (challenge->'paused'='true'::JSONB AND stimulus<>'{}'::JSONB) OR (stimulus ? 'reveal' AND (challenge->'solutionRevealed' IS DISTINCT FROM 'true'::JSONB OR challenge->'attemptsClosed' IS DISTINCT FROM 'true'::JSONB OR jsonb_typeof(stimulus->'reveal') IS DISTINCT FROM 'object' OR ((stimulus->'reveal')-allowed_reveal)<>'{}'::JSONB)) OR (challenge->>'kind'='memory' AND stimulus ? 'cells' AND challenge->>'stage'<>'observation') OR (challenge->>'kind'='qatar_map' AND stimulus->>'mode'='identify' AND stimulus ? 'namedPoints') THEN RETURN FALSE; END IF;
    IF challenge->>'stage' IN ('setup','countdown') AND ((challenge->>'kind' NOT IN ('memory','missing_tile')) OR (challenge->>'kind'='memory' AND (stimulus-ARRAY['rows','columns','palette','showSeconds','answerSeconds']::TEXT[])<>'{}'::JSONB) OR (challenge->>'kind'='missing_tile' AND (stimulus-ARRAY['rule']::TEXT[])<>'{}'::JSONB)) THEN RETURN FALSE; END IF;
    FOREACH list_key IN ARRAY ARRAY['cells','options','palette','markers','namedPoints'] LOOP
     IF stimulus ? list_key THEN
      IF jsonb_typeof(stimulus->list_key) IS DISTINCT FROM 'array' OR jsonb_array_length(stimulus->list_key)>217 THEN RETURN FALSE; END IF;
      list_fields:=CASE list_key WHEN 'cells' THEN CASE WHEN challenge->>'kind'='memory' THEN ARRAY['row','column','colorAr','hex','shapeAr'] ELSE ARRAY['row','column','id','labelAr','shape','hex','bitmask','missing'] END WHEN 'options' THEN ARRAY['id','labelAr','shape','hex','bitmask'] WHEN 'palette' THEN ARRAY['nameAr','hex'] WHEN 'markers' THEN ARRAY['id','x','y'] WHEN 'namedPoints' THEN ARRAY['id','nameAr'] ELSE ARRAY[]::TEXT[] END;
      FOR element IN SELECT value FROM jsonb_array_elements(stimulus->list_key) LOOP
       IF jsonb_typeof(element.value) IS DISTINCT FROM 'object' OR (element.value-list_fields)<>'{}'::JSONB THEN RETURN FALSE; END IF;
       FOR field IN SELECT key,value FROM jsonb_each(element.value) LOOP IF (field.key IN ('row','column','bitmask','x','y') AND jsonb_typeof(field.value) IS DISTINCT FROM 'number') OR (field.key='missing' AND jsonb_typeof(field.value) IS DISTINCT FROM 'boolean') OR (field.key NOT IN ('row','column','bitmask','x','y','missing') AND jsonb_typeof(field.value) IS DISTINCT FROM 'string') THEN RETURN FALSE; END IF; END LOOP;
      END LOOP;
     END IF;
    END LOOP;
    FOREACH list_key IN ARRAY ARRAY['start','goal','current'] LOOP IF stimulus ? list_key AND (jsonb_typeof(stimulus->list_key) IS DISTINCT FROM 'object' OR ((stimulus->list_key)-ARRAY['row','column']::TEXT[])<>'{}'::JSONB OR NOT (stimulus->list_key) ?& ARRAY['row','column'] OR jsonb_typeof(stimulus->list_key->'row') IS DISTINCT FROM 'number' OR jsonb_typeof(stimulus->list_key->'column') IS DISTINCT FROM 'number') THEN RETURN FALSE; END IF; END LOOP;
    IF stimulus ? 'blocked' THEN IF jsonb_typeof(stimulus->'blocked') IS DISTINCT FROM 'array' OR jsonb_array_length(stimulus->'blocked')>217 THEN RETURN FALSE; END IF; FOR element IN SELECT value FROM jsonb_array_elements(stimulus->'blocked') LOOP IF jsonb_typeof(element.value) IS DISTINCT FROM 'object' OR (element.value-ARRAY['row','column']::TEXT[])<>'{}'::JSONB OR NOT element.value ?& ARRAY['row','column'] OR jsonb_typeof(element.value->'row') IS DISTINCT FROM 'number' OR jsonb_typeof(element.value->'column') IS DISTINCT FROM 'number' THEN RETURN FALSE; END IF; END LOOP; END IF;
    FOREACH list_key IN ARRAY ARRAY['rows','columns','showSeconds','answerSeconds','answerSlots'] LOOP IF stimulus ? list_key AND (jsonb_typeof(stimulus->list_key) IS DISTINCT FROM 'number' OR stimulus->>list_key !~ '^(0|[1-9][0-9]{0,15})$') THEN RETURN FALSE; END IF; END LOOP;
    FOREACH list_key IN ARRAY ARRAY['rule','promptAr','instructionAr','mode','clueAr'] LOOP IF stimulus ? list_key AND jsonb_typeof(stimulus->list_key) IS DISTINCT FROM 'string' THEN RETURN FALSE; END IF; END LOOP;
    FOREACH list_key IN ARRAY ARRAY['optionIds','confirmedEdges'] LOOP IF stimulus ? list_key AND (jsonb_typeof(stimulus->list_key) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(stimulus->list_key) a WHERE jsonb_typeof(a) IS DISTINCT FROM 'string')) THEN RETURN FALSE; END IF; END LOOP;
    IF stimulus ? 'grid' THEN IF jsonb_typeof(stimulus->'grid') IS DISTINCT FROM 'array' THEN RETURN FALSE; END IF; FOR element IN SELECT value FROM jsonb_array_elements(stimulus->'grid') LOOP IF jsonb_typeof(element.value) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(element.value) a WHERE jsonb_typeof(a) IS DISTINCT FROM 'string') THEN RETURN FALSE; END IF; END LOOP; END IF;
    IF stimulus ? 'reveal' THEN
     FOREACH list_key IN ARRAY ARRAY['directions','answers','answerIds'] LOOP IF (stimulus->'reveal') ? list_key THEN IF jsonb_typeof(stimulus->'reveal'->list_key) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(stimulus->'reveal'->list_key) a WHERE jsonb_typeof(a) IS DISTINCT FROM 'string') THEN RETURN FALSE; END IF; END IF; END LOOP;
     IF (stimulus->'reveal') ? 'correctOptionId' AND jsonb_typeof(stimulus->'reveal'->'correctOptionId') IS DISTINCT FROM 'string' THEN RETURN FALSE; END IF;
     IF (stimulus->'reveal') ? 'paths' THEN IF jsonb_typeof(stimulus->'reveal'->'paths') IS DISTINCT FROM 'array' THEN RETURN FALSE; END IF; FOR element IN SELECT value FROM jsonb_array_elements(stimulus->'reveal'->'paths') LOOP IF jsonb_typeof(element.value) IS DISTINCT FROM 'object' OR (element.value-ARRAY['start','end']::TEXT[])<>'{}'::JSONB OR NOT element.value ?& ARRAY['start','end'] OR jsonb_typeof(element.value->'start') IS DISTINCT FROM 'object' OR jsonb_typeof(element.value->'end') IS DISTINCT FROM 'object' OR (element.value->'start'-ARRAY['row','column']::TEXT[])<>'{}'::JSONB OR (element.value->'end'-ARRAY['row','column']::TEXT[])<>'{}'::JSONB OR NOT (element.value->'start') ?& ARRAY['row','column'] OR NOT (element.value->'end') ?& ARRAY['row','column'] OR jsonb_typeof(element.value->'start'->'row') IS DISTINCT FROM 'number' OR jsonb_typeof(element.value->'start'->'column') IS DISTINCT FROM 'number' OR jsonb_typeof(element.value->'end'->'row') IS DISTINCT FROM 'number' OR jsonb_typeof(element.value->'end'->'column') IS DISTINCT FROM 'number' THEN RETURN FALSE; END IF; END LOOP; END IF;
    END IF;
   END IF;
  END IF;
  FOR item IN SELECT key,value FROM pg_catalog.jsonb_each(p_value) LOOP
   IF (lower(item.key)=ANY(ARRAY['canonicalanswer','correctanswer','privategrading','rawbytes','provenancebytes','capability','capabilities']) OR (NOT p_host AND lower(item.key)=ANY(ARRAY['acceptedanswers','primaryanswer','sources']))) OR NOT public.eng03_03_projection_safe(item.value,p_host) THEN RETURN FALSE; END IF;
  END LOOP;
 ELSIF jsonb_typeof(p_value)='array' THEN
  FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(p_value) LOOP IF NOT public.eng03_03_projection_safe(item.value,p_host) THEN RETURN FALSE; END IF; END LOOP;
 END IF;
 RETURN TRUE;
END $$;

CREATE OR REPLACE FUNCTION public.eng03_05_pointer_move(c JSONB,m JSONB,p JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE live JSONB; prior JSONB; ptr public."HuroofContentPointer"%ROWTYPE; current_data JSONB; target_data JSONB; scope TEXT; target TEXT; expected TEXT; next_version BIGINT; subj JSONB; result JSONB; evidence BYTEA;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p))<>11 OR NOT p ?& ARRAY['profileScope','expectedVersion','sourceId','revision','rawArtifactId','rawArtifactHash','validationReceiptId','catalogReleaseId','releaseRootHash','subject','authority'] OR EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE e.key NOT IN ('expectedVersion','subject','authority') AND jsonb_typeof(e.value) IS DISTINCT FROM 'string') OR jsonb_typeof(p->'subject') IS DISTINCT FROM 'object' OR jsonb_typeof(p->'authority') IS DISTINCT FROM 'object' OR (p->>'profileScope' !~ '^[A-Za-z0-9_-]{1,120}$' OR p->>'profileScope'='huroof-release-snapshot-v1') OR p->>'sourceId' !~ '^[A-Za-z0-9_-]{1,120}$' OR p->>'revision' !~ '^[1-9][0-9]{0,18}$' OR (p->>'revision')::NUMERIC>9223372036854775807 OR p->>'rawArtifactId' !~ '^[A-Za-z0-9_-]{1,120}$' OR p->>'rawArtifactHash' !~ '^[a-f0-9]{64}$' OR (p->'expectedVersion'<>'null'::JSONB AND (jsonb_typeof(p->'expectedVersion') IS DISTINCT FROM 'string' OR p->>'expectedVersion' !~ '^(0|[1-9][0-9]{0,18})$' OR (p->>'expectedVersion')::NUMERIC>9223372036854775806)) THEN RAISE EXCEPTION 'pointer unavailable'; END IF;
 scope:=p->>'profileScope'; expected:=p->>'expectedVersion'; target:='profile/'||scope;
 PERFORM public.eng03_05_lock_namespace(c->>'namespace'); live:=public.eng03_05_assert_admin(c,'releases.stage'); prior:=public.eng03_05_replay(c,m,'profile.pointer.move',target);
 IF m->'expectedRevision' IS DISTINCT FROM p->'expectedVersion' OR public.int5b_hash_json(jsonb_build_object('action','profile.pointer.move','target',target,'expectedRevision',m->'expectedRevision','payload',p)) IS DISTINCT FROM m->>'requestHash' THEN RAISE EXCEPTION 'mutation unavailable'; END IF;
 IF prior IS NOT NULL AND p->'subject'->>'schemaVersion'='huroof-gameplay-publication-subject-v1' THEN
  IF prior->'subject' IS DISTINCT FROM p->'subject' OR prior->'authority' IS DISTINCT FROM p->'authority' OR p->'subject'->>'kind' IS DISTINCT FROM 'pointer-move' OR p->'subject'->>'namespace' IS DISTINCT FROM c->>'namespace' OR p->'subject'->>'projectId' IS DISTINCT FROM c->>'projectId' OR p->'subject'->>'identityId' IS DISTINCT FROM c->>'identityId' OR p->'subject'->>'profileScope' IS DISTINCT FROM scope OR p->'subject'->>'profileSourceId' IS DISTINCT FROM p->>'sourceId' OR p->'subject'->>'profileRevision' IS DISTINCT FROM p->>'revision' OR p->'subject'->>'profileRawId' IS DISTINCT FROM p->>'rawArtifactId' OR p->'subject'->>'profileHash' IS DISTINCT FROM p->>'rawArtifactHash' OR jsonb_typeof(p->'subject'->'categories') IS DISTINCT FROM 'array' OR p->'authority'->>'subjectHash' IS DISTINCT FROM public.int5b_hash_json(p->'subject') OR (NOT (live->'roles' ? 'super_admin') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'subject'->'categories') category WHERE NOT (live->'categoryScopes' ? category))) THEN RAISE EXCEPTION 'pointer replay unavailable'; END IF;
  RETURN prior;
 END IF;
 PERFORM 1 FROM public."ActiveCatalogPointer" WHERE "id"='singleton' FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'pointer unavailable'; END IF;
 SELECT * INTO ptr FROM public."HuroofContentPointer" WHERE ("namespace","kind","scope")=(c->>'namespace','profile',scope) FOR UPDATE;
 IF ptr."scope" IS NOT NULL THEN IF ptr."family"<>'profile' THEN RAISE EXCEPTION 'pointer unavailable'; END IF; current_data:=public.eng03_05_prepare_profile(c,live,ptr."sourceId",ptr."revision"); IF current_data->>'rawArtifactHash' IS DISTINCT FROM ptr."rawArtifactHash" THEN RAISE EXCEPTION 'pointer unavailable'; END IF; END IF;
 target_data:=public.eng03_05_prepare_profile(c,live,p->>'sourceId',(p->>'revision')::BIGINT);
 IF target_data->>'rawArtifactId' IS DISTINCT FROM p->>'rawArtifactId' OR target_data->>'rawArtifactHash' IS DISTINCT FROM p->>'rawArtifactHash' OR target_data->'receipt'->>'id' IS DISTINCT FROM p->>'validationReceiptId' OR target_data->'receipt'->>'catalogId' IS DISTINCT FROM p->>'catalogReleaseId' OR target_data->'receipt'->>'catalogRoot' IS DISTINCT FROM p->>'releaseRootHash' THEN RAISE EXCEPTION 'pointer unavailable'; END IF;
 IF prior IS NOT NULL THEN RETURN prior; END IF;
 IF (ptr."scope" IS NULL AND expected IS NOT NULL) OR (ptr."scope" IS NOT NULL AND (expected IS NULL OR ptr."version"::TEXT IS DISTINCT FROM expected)) THEN RAISE EXCEPTION 'stale pointer'; END IF;
 subj:=jsonb_build_object('kind','pointer-move','namespace',c->>'namespace','projectId',c->>'projectId','identityId',c->>'identityId','identityPolicyRevision',c->>'policyRevision','identityPolicyHash',c->>'policyHash','profileScope',scope,'pointerVersion',CASE WHEN ptr."scope" IS NULL THEN NULL ELSE ptr."version"::TEXT END,'profileSourceId',target_data->>'sourceId','profileRevision',target_data->>'revision','profileRawId',target_data->>'rawArtifactId','profileHash',target_data->>'rawArtifactHash','snapshotId',target_data->'snapshot'->>'id','snapshotHash',target_data->'snapshot'->>'hash','snapshotProvenanceHash',target_data->'snapshot'->>'provenanceHash','releaseId',target_data->'receipt'->>'releaseId','releaseRoot',target_data->'receipt'->>'releaseRoot','receiptId',target_data->'receipt'->>'id','catalogId',target_data->'receipt'->>'catalogId','catalogRoot',target_data->'receipt'->>'catalogRoot','sealHash',target_data->'receipt'->>'sealHash','categories',target_data->'categories');
 IF target_data->>'rawSerialization'='huroof-gameplay-profile-v1' THEN
  IF convert_from(decode(target_data->>'profileRawBase64','base64'),'UTF8')::JSONB->'supplement'->>'serialization'='huroof-gameplay-map-supplement-v2' THEN RAISE EXCEPTION 'map supplier unavailable'; END IF;
  IF convert_from(decode(target_data->>'profileRawBase64','base64'),'UTF8')::JSONB->'supplement' IS DISTINCT FROM 'null'::JSONB AND convert_from(decode(target_data->>'profileRawBase64','base64'),'UTF8')::JSONB->'categories' ? 'tahadani-games-326' THEN RAISE EXCEPTION 'map supplier unavailable'; END IF;
  subj:=subj||jsonb_build_object('schemaVersion','huroof-gameplay-publication-subject-v1','profileRaw',jsonb_build_object('namespace',c->>'namespace','id',target_data->>'rawArtifactId','hash',target_data->>'rawArtifactHash','byteLength',(target_data->>'rawByteLength')::BIGINT,'mediaType',target_data->>'rawMediaType','serialization',target_data->>'rawSerialization','provenanceHash',target_data->>'rawProvenanceHash'),'supplement',convert_from(decode(target_data->>'profileRawBase64','base64'),'UTF8')::JSONB->'supplement','sourceManifestSha256',target_data->'receipt'->>'sourceEvidenceManifestHash');
 END IF;
 IF p->'subject' IS DISTINCT FROM subj THEN RAISE EXCEPTION 'stale pointer subject'; END IF; PERFORM public.eng03_05_assert_evidence(subj,p->'authority');
 next_version:=CASE WHEN ptr."scope" IS NULL THEN 0 ELSE ptr."version"+1 END;
 result:=jsonb_build_object('operationId',m->>'operationId','revision',next_version::TEXT,'status','moved','subject',subj,'authority',p->'authority');
 INSERT INTO public."HuroofAdminOperation"("namespace","operationId","actorIdentityId","actorAuthzVersion","actorRoles","actorProjectId","actorPolicyRevision","actorPolicyHash","action","target","scope","requestHash","expectedRevision","resultRevision","resultCode","result") VALUES(c->>'namespace',m->>'operationId',c->>'identityId',(c->>'claimAuthzVersion')::BIGINT,ARRAY(SELECT jsonb_array_elements_text(c->'claimRoles')),c->>'projectId',c->>'policyRevision',c->>'policyHash','profile.pointer.move',target,scope,m->>'requestHash',CASE WHEN expected IS NULL THEN NULL ELSE expected::BIGINT END,next_version,'moved',result);
 IF ptr."scope" IS NULL THEN INSERT INTO public."HuroofContentPointer"("namespace","kind","scope","family","sourceId","revision","rawArtifactHash","version") VALUES(c->>'namespace','profile',scope,'profile',p->>'sourceId',(p->>'revision')::BIGINT,p->>'rawArtifactHash',0);
 ELSE UPDATE public."HuroofContentPointer" SET "family"='profile',"sourceId"=p->>'sourceId',"revision"=(p->>'revision')::BIGINT,"rawArtifactHash"=p->>'rawArtifactHash',"version"=next_version,"updatedAt"=clock_timestamp() WHERE ("namespace","kind","scope","version")=(c->>'namespace','profile',scope,expected::BIGINT); IF NOT FOUND THEN RAISE EXCEPTION 'stale pointer'; END IF; END IF;
 evidence:=convert_to(public.int5b_canonical_json(jsonb_build_object('subject',subj,'authority',p->'authority','expectedVersion',p->'expectedVersion')),'UTF8');
 INSERT INTO public."HuroofContentAudit"("namespace","operationKey","actorFirebaseIdentityId","kind","scope","expectedVersion","outcome","rawEvidence","evidenceHash") VALUES(c->>'namespace',m->>'operationId',c->>'identityId','profile',scope,COALESCE(expected::BIGINT,0),CASE WHEN expected IS NULL THEN 'created' ELSE 'moved' END,evidence,encode(int4_crypto.digest(evidence,'sha256'),'hex'));
 PERFORM public.eng03_05_append_audit(c->>'namespace',m->>'operationId','mutation'); UPDATE public."HuroofAdminAuthzInvariant" SET "revision"="revision"+1 WHERE "namespace"=c->>'namespace'; RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.eng03_05_profile_append(c JSONB,m JSONB,p JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE live JSONB; prior JSONB; metadata JSONB; raw_bytes BYTEA; provenance BYTEA; raw_hash TEXT; prov_hash TEXT; profile JSONB; ref JSONB; snap public."HuroofRawArtifact"%ROWTYPE; old_raw public."HuroofRawArtifact"%ROWTYPE; old_snap public."HuroofRawArtifact"%ROWTYPE; existing public."HuroofRawArtifact"%ROWTYPE; prev public."HuroofContentRevision"%ROWTYPE; rec public."CatalogValidationReceipt"%ROWTYPE; pointer public."HuroofContentPointer"%ROWTYPE; pointer_data JSONB; predecessor_data JSONB; expected BIGINT; cats JSONB; old_ref JSONB; subj JSONB; result JSONB; target TEXT; scope TEXT; gameplay_proof JSONB; supp_ref JSONB; supp public."HuroofRawArtifact"%ROWTYPE; supp_proof JSONB; supp_doc JSONB;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p))<>22 OR NOT p ?& ARRAY['profileScope','sourceId','revision','rawArtifactId','rawArtifactHash','byteLength','mediaType','serialization','provenanceHash','profileBase64','provenanceBase64','previousRevision','previousHash','previousRawArtifactId','validationReceiptId','catalogReleaseId','releaseRootHash','snapshotId','snapshotHash','snapshotProvenanceHash','subject','authority'] OR EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE e.key NOT IN ('previousRevision','previousHash','previousRawArtifactId','subject','authority') AND jsonb_typeof(e.value) IS DISTINCT FROM 'string') OR jsonb_typeof(p->'subject') IS DISTINCT FROM 'object' OR jsonb_typeof(p->'authority') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE e.key IN ('previousRevision','previousHash','previousRawArtifactId') AND jsonb_typeof(e.value) NOT IN ('string','null')) OR (p->>'profileScope' !~ '^[A-Za-z0-9_-]{1,120}$' OR p->>'profileScope'='huroof-release-snapshot-v1') OR p->>'sourceId' !~ '^[A-Za-z0-9_-]{1,120}$' OR p->>'rawArtifactId' !~ '^[A-Za-z0-9_-]{1,120}$' OR p->>'sourceId'='eng03.custody-authority.v1' OR p->>'rawArtifactHash' !~ '^[a-f0-9]{64}$' OR p->>'provenanceHash' !~ '^[a-f0-9]{64}$' OR p->>'snapshotHash' !~ '^[a-f0-9]{64}$' OR p->>'snapshotProvenanceHash' !~ '^[a-f0-9]{64}$' OR p->>'mediaType' IS DISTINCT FROM 'application/json' OR p->>'serialization' IN ('huroof-custody-authority-policy-v1','huroof-release-snapshot-v1') OR p->>'serialization' !~ '^[A-Za-z0-9._:-]{1,200}$' OR p->>'byteLength' !~ '^[1-9][0-9]{0,7}$' OR (p->>'byteLength')::NUMERIC>67108864 OR p->>'revision' !~ '^[1-9][0-9]{0,15}$' OR length(p->>'profileBase64')>89478488 OR length(p->>'provenanceBase64')>89478488 OR p->>'profileBase64' !~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' OR p->>'provenanceBase64' !~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 raw_bytes:=decode(p->>'profileBase64','base64'); provenance:=decode(p->>'provenanceBase64','base64'); raw_hash:=encode(int4_crypto.digest(raw_bytes,'sha256'),'hex'); prov_hash:=encode(int4_crypto.digest(provenance,'sha256'),'hex');
 IF octet_length(raw_bytes)<>(p->>'byteLength')::BIGINT OR octet_length(provenance)>67108864 OR raw_hash IS DISTINCT FROM p->>'rawArtifactHash' OR prov_hash IS DISTINCT FROM p->>'provenanceHash' OR replace(replace(encode(raw_bytes,'base64'),chr(10),''),chr(13),'') IS DISTINCT FROM p->>'profileBase64' OR replace(replace(encode(provenance,'base64'),chr(10),''),chr(13),'') IS DISTINCT FROM p->>'provenanceBase64' THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 profile:=convert_from(raw_bytes,'UTF8')::JSONB; ref:=profile->'contentSnapshot';
 IF (p->>'serialization' LIKE 'huroof-gameplay-profile-%' OR profile->>'schemaVersion' LIKE 'huroof-gameplay-profile-%') AND (p->>'serialization' IS DISTINCT FROM 'huroof-gameplay-profile-v1' OR profile->>'schemaVersion' IS DISTINCT FROM 'huroof-gameplay-profile-v1') THEN RAISE EXCEPTION 'reserved gameplay profile unavailable'; END IF;
 IF jsonb_typeof(profile) IS DISTINCT FROM 'object' OR jsonb_typeof(ref) IS DISTINCT FROM 'object' OR ref->>'namespace' IS DISTINCT FROM c->>'namespace' OR ref->>'id' IS DISTINCT FROM p->>'snapshotId' OR ref->>'hash' IS DISTINCT FROM p->>'snapshotHash' OR ref->>'provenanceHash' IS DISTINCT FROM p->>'snapshotProvenanceHash' OR ref->>'mediaType' IS DISTINCT FROM 'application/json' OR ref->>'serialization' IS DISTINCT FROM 'huroof-release-snapshot-v1' THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 scope:=p->>'profileScope'; target:='profile/'||(p->>'sourceId'); metadata:=p-'profileBase64'-'provenanceBase64';
 PERFORM public.eng03_05_lock_namespace(c->>'namespace'); live:=public.eng03_05_assert_admin(c,'releases.stage'); prior:=public.eng03_05_replay(c,m,'profile.append',target);
 IF m->'expectedRevision'='null'::JSONB OR public.int5b_hash_json(jsonb_build_object('action','profile.append','target',target,'expectedRevision',m->'expectedRevision','payload',metadata)) IS DISTINCT FROM m->>'requestHash' THEN RAISE EXCEPTION 'mutation unavailable'; END IF; expected:=(m->>'expectedRevision')::BIGINT;
 IF p->>'revision' IS DISTINCT FROM (expected+1)::TEXT THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 IF prior IS NOT NULL AND p->>'serialization'='huroof-gameplay-profile-v1' THEN
  SELECT * INTO existing FROM public."HuroofRawArtifact" WHERE ("namespace","id")=(c->>'namespace',p->>'rawArtifactId');
  IF NOT FOUND OR existing."rawBytes" IS DISTINCT FROM raw_bytes OR existing."provenanceBytes" IS DISTINCT FROM provenance OR existing."contentHash" IS DISTINCT FROM raw_hash OR existing."provenanceHash" IS DISTINCT FROM prov_hash OR existing."byteLength" IS DISTINCT FROM octet_length(raw_bytes) OR existing."mediaType" IS DISTINCT FROM p->>'mediaType' OR existing."serialization" IS DISTINCT FROM p->>'serialization' OR prior->'descriptor' IS DISTINCT FROM metadata OR prior->'subject' IS DISTINCT FROM p->'subject' OR prior->'authority' IS DISTINCT FROM p->'authority' OR p->'subject'->>'schemaVersion' IS DISTINCT FROM 'huroof-gameplay-publication-subject-v1' OR p->'subject'->>'kind' IS DISTINCT FROM 'profile-append' OR p->'subject'->>'namespace' IS DISTINCT FROM c->>'namespace' OR p->'subject'->>'projectId' IS DISTINCT FROM c->>'projectId' OR p->'subject'->>'identityId' IS DISTINCT FROM c->>'identityId' OR p->'subject'->>'profileScope' IS DISTINCT FROM scope OR p->'subject'->>'profileSourceId' IS DISTINCT FROM p->>'sourceId' OR p->'subject'->>'profileRevision' IS DISTINCT FROM p->>'revision' OR p->'subject'->>'profileHash' IS DISTINCT FROM raw_hash OR jsonb_typeof(p->'subject'->'categories') IS DISTINCT FROM 'array' OR p->'authority'->>'subjectHash' IS DISTINCT FROM public.int5b_hash_json(p->'subject') OR (NOT (live->'roles' ? 'super_admin') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'subject'->'categories') category WHERE NOT (live->'categoryScopes' ? category))) THEN RAISE EXCEPTION 'profile replay unavailable'; END IF;
  RETURN prior;
 END IF;
 PERFORM 1 FROM public."ActiveCatalogPointer" WHERE "id"='singleton' FOR SHARE;
 SELECT * INTO pointer FROM public."HuroofContentPointer" WHERE ("namespace","kind","scope")=(c->>'namespace','profile',scope) FOR SHARE; IF pointer."scope" IS NOT NULL AND pointer."family"<>'profile' THEN RAISE EXCEPTION 'profile unavailable'; END IF; IF pointer."scope" IS NOT NULL THEN pointer_data:=public.eng03_05_prepare_profile(c,live,pointer."sourceId",pointer."revision"); IF pointer_data->>'rawArtifactHash' IS DISTINCT FROM pointer."rawArtifactHash" THEN RAISE EXCEPTION 'profile unavailable'; END IF; END IF;

 SELECT * INTO snap FROM public."HuroofRawArtifact" WHERE "namespace"=c->>'namespace' AND "id"=p->>'snapshotId' AND "contentHash"=p->>'snapshotHash' AND "provenanceHash"=p->>'snapshotProvenanceHash' AND "byteLength"::TEXT=ref->>'byteLength' AND "mediaType"=ref->>'mediaType' AND "serialization"=ref->>'serialization'; IF NOT FOUND THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 SELECT receipt.* INTO rec FROM public."CatalogValidationReceipt" receipt JOIN public."CatalogReleaseSeal" seal ON (seal."catalogReleaseId",seal."releaseRootHash",seal."sealHash")=(receipt."catalogReleaseId",receipt."releaseRootHash",receipt."sealHash") WHERE (receipt."id",receipt."catalogReleaseId",receipt."releaseRootHash")=(p->>'validationReceiptId',p->>'catalogReleaseId',p->>'releaseRootHash') AND receipt."huroofProjectId"=c->>'projectId';
 IF NOT FOUND OR public.eng03_05_snapshot_documents_root(snap."rawBytes") IS DISTINCT FROM rec."huroofRootSha256" OR convert_from(snap."rawBytes",'UTF8')::JSON->>'releaseId' IS DISTINCT FROM rec."huroofReleaseId" THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 SELECT COALESCE(jsonb_agg(id ORDER BY id COLLATE "C"),'[]'::JSONB) INTO cats FROM (SELECT split_part(e->>'path','/',4) id FROM json_array_elements(convert_from(snap."rawBytes",'UTF8')::JSON->'documents') e WHERE split_part(e->>'path','/',3)='catalogCategories') x;
 IF NOT (live->'roles' ? 'super_admin') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(cats) e(id) WHERE NOT (live->'categoryScopes' ? id)) THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 IF expected=0 THEN IF p->'previousRevision'<>'null'::JSONB OR p->'previousHash'<>'null'::JSONB OR p->'previousRawArtifactId'<>'null'::JSONB THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 ELSE SELECT * INTO prev FROM public."HuroofContentRevision" WHERE ("namespace","family","sourceId","revision")=(c->>'namespace','profile',p->>'sourceId',expected);
  IF NOT FOUND OR p->>'previousRevision' IS DISTINCT FROM expected::TEXT OR p->>'previousHash' IS DISTINCT FROM prev."rawArtifactHash" OR p->>'previousRawArtifactId' IS DISTINCT FROM prev."rawArtifactId" THEN RAISE EXCEPTION 'profile unavailable'; END IF; predecessor_data:=public.eng03_05_prepare_profile(c,live,p->>'sourceId',expected); IF predecessor_data->>'rawArtifactHash' IS DISTINCT FROM prev."rawArtifactHash" THEN RAISE EXCEPTION 'profile unavailable'; END IF;
  SELECT * INTO old_raw FROM public."HuroofRawArtifact" WHERE ("namespace","id","contentHash")=(prev."namespace",prev."rawArtifactId",prev."rawArtifactHash"); IF NOT FOUND THEN RAISE EXCEPTION 'profile unavailable'; END IF; old_ref:=convert_from(old_raw."rawBytes",'UTF8')::JSONB->'contentSnapshot'; IF jsonb_typeof(old_ref) IS DISTINCT FROM 'object' OR old_ref->>'namespace' IS DISTINCT FROM c->>'namespace' OR old_ref->>'mediaType' IS DISTINCT FROM 'application/json' OR old_ref->>'serialization' IS DISTINCT FROM 'huroof-release-snapshot-v1' THEN RAISE EXCEPTION 'profile unavailable'; END IF;
  SELECT * INTO old_snap FROM public."HuroofRawArtifact" WHERE "namespace"=c->>'namespace' AND "id"=old_ref->>'id' AND "contentHash"=old_ref->>'hash' AND "provenanceHash"=old_ref->>'provenanceHash' AND "byteLength"::TEXT=old_ref->>'byteLength' AND "mediaType"='application/json' AND "serialization"='huroof-release-snapshot-v1'; IF NOT FOUND THEN RAISE EXCEPTION 'profile unavailable'; END IF; PERFORM public.eng03_05_snapshot_documents_root(old_snap."rawBytes");
  IF NOT (live->'roles' ? 'super_admin') AND EXISTS(SELECT 1 FROM json_array_elements(convert_from(old_snap."rawBytes",'UTF8')::JSON->'documents') e WHERE split_part(e->>'path','/',3)='catalogCategories' AND NOT (live->'categoryScopes' ? split_part(e->>'path','/',4))) THEN RAISE EXCEPTION 'profile unavailable'; END IF;
 END IF;
 IF prior IS NOT NULL THEN RETURN prior; END IF;
 IF EXISTS(SELECT 1 FROM public."HuroofContentRevision" r WHERE (r."namespace",r."family",r."sourceId")=(c->>'namespace','profile',p->>'sourceId') AND r."revision">expected) OR NOT EXISTS(SELECT 1 FROM public."ActiveCatalogPointer" a WHERE a."id"='singleton' AND (a."validationReceiptId",a."catalogReleaseId",a."releaseRootHash")=(rec."id",rec."catalogReleaseId",rec."releaseRootHash")) THEN RAISE EXCEPTION 'stale profile'; END IF;

 subj:=jsonb_build_object('kind','profile-append','namespace',c->>'namespace','projectId',c->>'projectId','identityId',c->>'identityId','identityPolicyRevision',c->>'policyRevision','identityPolicyHash',c->>'policyHash','profileScope',scope,'pointerVersion',CASE WHEN pointer."scope" IS NULL THEN NULL ELSE pointer."version"::TEXT END,'profileSourceId',p->>'sourceId','profileRevision',p->>'revision','profileRawId',p->>'rawArtifactId','profileHash',raw_hash,'snapshotId',snap."id",'snapshotHash',snap."contentHash",'snapshotProvenanceHash',snap."provenanceHash",'releaseId',rec."huroofReleaseId",'releaseRoot',rec."huroofRootSha256",'receiptId',rec."id",'catalogId',rec."catalogReleaseId",'catalogRoot',rec."releaseRootHash",'sealHash',rec."sealHash",'categories',cats);
 IF p->>'serialization'='huroof-gameplay-profile-v1' THEN
  gameplay_proof:=convert_from(provenance,'UTF8')::JSONB; supp_ref:=profile->'supplement';
  IF jsonb_typeof(profile->'categories') IS DISTINCT FROM 'array' OR jsonb_array_length(profile->'categories') NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY['gameKind','mode','modality','mapPresentation']) k WHERE jsonb_typeof(profile->k) IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(profile->'categories') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR x#>>'{}' !~ '^[A-Za-z0-9_-]{1,120}$') OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(profile->'categories') x)<>jsonb_array_length(profile->'categories') OR profile->>'gameKind' NOT IN ('huroof','categories') OR profile->>'mode' NOT IN ('classic','fast','custom') OR profile->>'modality' NOT IN ('classic','image','video','charades') OR profile->>'mapPresentation' NOT IN ('ordinary','interactive') OR jsonb_typeof(profile->'questionSeconds') IS DISTINCT FROM 'number' OR profile->>'questionSeconds' !~ '^[0-9]{1,3}$' OR (profile->>'questionSeconds')::INTEGER NOT BETWEEN 5 AND 120 OR jsonb_typeof(profile->'opponentSeconds') IS DISTINCT FROM 'number' OR profile->>'opponentSeconds' !~ '^[0-9]{1,3}$' OR (profile->>'opponentSeconds')::INTEGER NOT BETWEEN 5 AND 120 OR (profile->>'modality'='charades' AND profile->'challenge' IS DISTINCT FROM 'null'::JSONB) THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF jsonb_typeof(profile->'release') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'release'))<>7 OR NOT (profile->'release') ?& ARRAY['id','rootSha256','receiptId','catalogId','catalogRoot','sealHash','sourceManifestHash'] OR jsonb_typeof(profile->'selector') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'selector'))<>2 OR NOT (profile->'selector') ?& ARRAY['version','capabilityStateHash'] OR jsonb_typeof(profile->'readiness') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'readiness'))<>1 OR NOT (profile->'readiness') ? 'policyVersion' OR jsonb_typeof(profile->'custody') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'custody'))<>2 OR NOT (profile->'custody') ?& ARRAY['policyRevision','policyHash'] OR profile->'custody'->>'policyRevision' !~ '^[1-9][0-9]*$' OR profile->'custody'->>'policyHash' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(profile->'release') e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string') OR EXISTS(SELECT 1 FROM jsonb_each(profile->'selector') e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string') OR EXISTS(SELECT 1 FROM jsonb_each(profile->'readiness') e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string') OR EXISTS(SELECT 1 FROM jsonb_each(profile->'custody') e WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF profile->'challenge' IS DISTINCT FROM 'null'::JSONB THEN
   IF jsonb_typeof(profile->'challenge') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'challenge'))<>3 OR NOT (profile->'challenge') ?& ARRAY['protocolVersion','mechanics','definitionSchemas'] OR profile->'challenge'->>'protocolVersion' IS DISTINCT FROM 't36-challenge-runtime-v1' OR jsonb_typeof(profile->'challenge'->'mechanics') IS DISTINCT FROM 'array' OR jsonb_typeof(profile->'challenge'->'definitionSchemas') IS DISTINCT FROM 'array' OR jsonb_array_length(profile->'challenge'->'mechanics') NOT BETWEEN 1 AND 5 OR jsonb_array_length(profile->'challenge'->'definitionSchemas') NOT BETWEEN 1 AND 3 OR EXISTS(SELECT 1 FROM jsonb_array_elements(profile->'challenge'->'mechanics') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR x#>>'{}' NOT IN ('navigation','missing_tile','memory','qatar_map','word_search')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(profile->'challenge'->'definitionSchemas') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR x#>>'{}' NOT IN ('t36-challenge-definition-v1','t37-clean70-challenge-definition-v1','t37-topup-word-search-definition-v1')) OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(profile->'challenge'->'mechanics') x)<>jsonb_array_length(profile->'challenge'->'mechanics') OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(profile->'challenge'->'definitionSchemas') x)<>jsonb_array_length(profile->'challenge'->'definitionSchemas') THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  END IF;
  IF profile->>'mapPresentation'='interactive' AND (jsonb_typeof(profile->'challenge'->'mechanics') IS DISTINCT FROM 'array' OR NOT (profile->'challenge'->'mechanics') ? 'qatar_map') THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF supp_ref='null'::JSONB AND (profile->'challenge' IS DISTINCT FROM 'null'::JSONB OR profile->>'mapPresentation' IS DISTINCT FROM 'ordinary') THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF supp_ref IS DISTINCT FROM 'null'::JSONB AND profile->'categories' ? 'tahadani-games-326' THEN RAISE EXCEPTION 'map supplier unavailable'; END IF;
  IF convert_from(raw_bytes,'UTF8') IS DISTINCT FROM public.int5b_canonical_json(profile) OR jsonb_typeof(profile) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile))<>18 OR NOT profile ?& ARRAY['schemaVersion','namespace','profileScope','sourceId','gameKind','mode','modality','categories','questionSeconds','opponentSeconds','mapPresentation','challenge','release','contentSnapshot','supplement','selector','readiness','custody'] OR profile->>'schemaVersion' IS DISTINCT FROM p->>'serialization' OR profile->>'namespace' IS DISTINCT FROM c->>'namespace' OR profile->>'profileScope' IS DISTINCT FROM scope OR profile->>'sourceId' IS DISTINCT FROM p->>'sourceId' OR profile->'release'->>'id' IS DISTINCT FROM rec."huroofReleaseId" OR profile->'release'->>'rootSha256' IS DISTINCT FROM rec."huroofRootSha256" OR profile->'release'->>'receiptId' IS DISTINCT FROM rec."id" OR profile->'release'->>'catalogId' IS DISTINCT FROM rec."catalogReleaseId" OR profile->'release'->>'catalogRoot' IS DISTINCT FROM rec."releaseRootHash" OR profile->'release'->>'sealHash' IS DISTINCT FROM rec."sealHash" OR profile->'release'->>'sourceManifestHash' IS DISTINCT FROM rec."sourceEvidenceManifestHash" OR profile->'selector'->>'version' IS DISTINCT FROM rec."selectorVersion" OR profile->'selector'->>'capabilityStateHash' IS DISTINCT FROM rec."huroofCapabilityStateHash" OR profile->'readiness'->>'policyVersion' IS DISTINCT FROM rec."policyVersion" OR convert_from(provenance,'UTF8') IS DISTINCT FROM public.int5b_canonical_json(gameplay_proof) OR jsonb_typeof(gameplay_proof) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(gameplay_proof))<>8 OR NOT gameplay_proof ?& ARRAY['schemaVersion','namespace','profileScope','profileSourceId','contentHash','contentSnapshot','supplement','sourceManifestSha256'] OR gameplay_proof->>'schemaVersion' IS DISTINCT FROM 'huroof-gameplay-profile-provenance-v1' OR gameplay_proof->>'namespace' IS DISTINCT FROM c->>'namespace' OR gameplay_proof->>'profileScope' IS DISTINCT FROM scope OR gameplay_proof->>'profileSourceId' IS DISTINCT FROM p->>'sourceId' OR gameplay_proof->>'contentHash' IS DISTINCT FROM raw_hash OR gameplay_proof->'contentSnapshot' IS DISTINCT FROM ref OR gameplay_proof->'supplement' IS DISTINCT FROM supp_ref OR gameplay_proof->>'sourceManifestSha256' IS DISTINCT FROM rec."sourceEvidenceManifestHash" THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF supp_ref IS DISTINCT FROM 'null'::JSONB THEN
   IF supp_ref->>'serialization'='huroof-gameplay-map-supplement-v2' THEN RAISE EXCEPTION 'map supplier unavailable'; END IF;
   IF jsonb_typeof(supp_ref) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(supp_ref))<>7 OR NOT supp_ref ?& ARRAY['namespace','id','hash','byteLength','mediaType','serialization','provenanceHash'] OR supp_ref->>'namespace' IS DISTINCT FROM c->>'namespace' OR supp_ref->>'mediaType' IS DISTINCT FROM 'application/json' OR supp_ref->>'serialization' NOT IN ('huroof-gameplay-supplement-v1','huroof-gameplay-map-supplement-v2') OR jsonb_typeof(supp_ref->'byteLength') IS DISTINCT FROM 'number' OR supp_ref->>'byteLength' !~ '^[1-9][0-9]{0,7}$' OR (supp_ref->>'byteLength')::NUMERIC>67108864 THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
   SELECT * INTO supp FROM public."HuroofRawArtifact" WHERE ("namespace","id","contentHash","byteLength","mediaType","serialization","provenanceHash")=(c->>'namespace',supp_ref->>'id',supp_ref->>'hash',(supp_ref->>'byteLength')::BIGINT,supp_ref->>'mediaType',supp_ref->>'serialization',supp_ref->>'provenanceHash');
   IF NOT FOUND OR octet_length(supp."rawBytes")<>supp."byteLength" OR octet_length(supp."provenanceBytes") NOT BETWEEN 1 AND 67108864 OR encode(int4_crypto.digest(supp."rawBytes",'sha256'),'hex') IS DISTINCT FROM supp."contentHash" OR encode(int4_crypto.digest(supp."provenanceBytes",'sha256'),'hex') IS DISTINCT FROM supp."provenanceHash" THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
   supp_proof:=convert_from(supp."provenanceBytes",'UTF8')::JSONB; supp_doc:=convert_from(supp."rawBytes",'UTF8')::JSONB;
   IF jsonb_typeof(supp_proof) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(supp_proof))<>CASE WHEN supp."serialization"='huroof-gameplay-map-supplement-v2' THEN 11 ELSE 10 END OR NOT supp_proof ?& ARRAY['schemaVersion','namespace','profileScope','profileSourceId','releaseId','releaseRootSha256','receiptId','sourceManifestSha256','contentHash','contentSnapshot'] OR (supp."serialization"='huroof-gameplay-map-supplement-v2' AND jsonb_typeof(supp_proof->'mapRootEvidence') IS DISTINCT FROM 'object') THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
   IF convert_from(supp."rawBytes",'UTF8') IS DISTINCT FROM public.int5b_canonical_json(supp_doc) OR jsonb_typeof(supp_doc) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(supp_doc))<>CASE WHEN supp."serialization"='huroof-gameplay-map-supplement-v2' THEN 12 ELSE 9 END OR NOT supp_doc ?& ARRAY['schemaVersion','namespace','profileScope','profileSourceId','releaseId','releaseRootSha256','sourceManifestSha256','definitions','maps'] OR (supp."serialization"='huroof-gameplay-map-supplement-v2' AND NOT supp_doc ?& ARRAY['definitionSet','mapCommitment','geographicOverlaySha256']) OR supp_doc->>'schemaVersion' IS DISTINCT FROM supp."serialization" OR supp_doc->>'namespace' IS DISTINCT FROM c->>'namespace' OR supp_doc->>'profileScope' IS DISTINCT FROM scope OR supp_doc->>'profileSourceId' IS DISTINCT FROM p->>'sourceId' OR supp_doc->>'releaseId' IS DISTINCT FROM rec."huroofReleaseId" OR supp_doc->>'releaseRootSha256' IS DISTINCT FROM rec."huroofRootSha256" OR supp_doc->>'sourceManifestSha256' IS DISTINCT FROM rec."sourceEvidenceManifestHash" THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
   IF convert_from(supp."provenanceBytes",'UTF8') IS DISTINCT FROM public.int5b_canonical_json(supp_proof) OR supp_proof->>'schemaVersion' IS DISTINCT FROM CASE WHEN supp."serialization"='huroof-gameplay-map-supplement-v2' THEN 'huroof-gameplay-map-supplement-provenance-v2' ELSE 'huroof-gameplay-supplement-provenance-v1' END OR supp_proof->>'namespace' IS DISTINCT FROM c->>'namespace' OR supp_proof->>'profileScope' IS DISTINCT FROM scope OR supp_proof->>'profileSourceId' IS DISTINCT FROM p->>'sourceId' OR supp_proof->>'releaseId' IS DISTINCT FROM rec."huroofReleaseId" OR supp_proof->>'releaseRootSha256' IS DISTINCT FROM rec."huroofRootSha256" OR supp_proof->>'receiptId' IS DISTINCT FROM rec."id" OR supp_proof->>'sourceManifestSha256' IS DISTINCT FROM rec."sourceEvidenceManifestHash" OR supp_proof->>'contentHash' IS DISTINCT FROM supp."contentHash" OR supp_proof->'contentSnapshot' IS DISTINCT FROM ref THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  END IF;
  subj:=subj||jsonb_build_object('schemaVersion','huroof-gameplay-publication-subject-v1','profileRaw',jsonb_build_object('namespace',c->>'namespace','id',p->>'rawArtifactId','hash',raw_hash,'byteLength',octet_length(raw_bytes),'mediaType',p->>'mediaType','serialization',p->>'serialization','provenanceHash',prov_hash),'supplement',supp_ref,'sourceManifestSha256',rec."sourceEvidenceManifestHash");
 END IF;
 IF p->'subject' IS DISTINCT FROM subj THEN RAISE EXCEPTION 'stale profile subject'; END IF; PERFORM public.eng03_05_assert_evidence(subj,p->'authority');
 SELECT * INTO existing FROM public."HuroofRawArtifact" WHERE ("namespace","id")=(c->>'namespace',p->>'rawArtifactId');
 IF FOUND AND (existing."rawBytes" IS DISTINCT FROM raw_bytes OR existing."contentHash" IS DISTINCT FROM raw_hash OR existing."mediaType" IS DISTINCT FROM p->>'mediaType' OR existing."serialization" IS DISTINCT FROM p->>'serialization' OR existing."provenanceBytes" IS DISTINCT FROM provenance OR existing."provenanceHash" IS DISTINCT FROM prov_hash) THEN RAISE EXCEPTION 'immutable raw conflict'; END IF;
 result:=jsonb_build_object('operationId',m->>'operationId','revision',(expected+1)::TEXT,'status','profile_appended','subject',subj,'authority',p->'authority','descriptor',metadata);
 INSERT INTO public."HuroofAdminOperation"("namespace","operationId","actorIdentityId","actorAuthzVersion","actorRoles","actorProjectId","actorPolicyRevision","actorPolicyHash","action","target","scope","requestHash","expectedRevision","resultRevision","resultCode","result") VALUES(c->>'namespace',m->>'operationId',c->>'identityId',(c->>'claimAuthzVersion')::BIGINT,ARRAY(SELECT jsonb_array_elements_text(c->'claimRoles')),c->>'projectId',c->>'policyRevision',c->>'policyHash','profile.append',target,scope,m->>'requestHash',expected,expected+1,'profile_appended',result);
 IF existing."id" IS NULL THEN INSERT INTO public."HuroofRawArtifact"("namespace","id","contentHash","byteLength","mediaType","rawBytes","provenanceBytes","provenanceHash","serialization") VALUES(c->>'namespace',p->>'rawArtifactId',raw_hash,octet_length(raw_bytes),p->>'mediaType',raw_bytes,provenance,prov_hash,p->>'serialization'); END IF;
 INSERT INTO public."HuroofContentRevision"("namespace","family","sourceId","revision","rawArtifactId","rawArtifactHash","previousRevision","previousHash","previousRawArtifactId","validationReceiptId","catalogReleaseId","releaseRootHash","actorFirebaseIdentityId") VALUES(c->>'namespace','profile',p->>'sourceId',expected+1,p->>'rawArtifactId',raw_hash,CASE WHEN expected=0 THEN NULL ELSE expected END,CASE WHEN expected=0 THEN NULL ELSE prev."rawArtifactHash" END,CASE WHEN expected=0 THEN NULL ELSE prev."rawArtifactId" END,rec."id",rec."catalogReleaseId",rec."releaseRootHash",c->>'identityId');
 PERFORM public.eng03_05_append_audit(c->>'namespace',m->>'operationId','mutation'); UPDATE public."HuroofAdminAuthzInvariant" SET "revision"="revision"+1 WHERE "namespace"=c->>'namespace'; RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.eng03_03_paid_start(p_identity TEXT,p_request_key TEXT,p_logical_match_id TEXT,p_intent JSONB,p_initial JSONB,p_projections JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE
 w public."Wallet"%ROWTYPE; identity_row public."FirebaseIdentity"%ROWTYPE; namespace_row public."DeploymentNamespace"%ROWTYPE;
 request_admission public."Admission"%ROWTYPE; logical_admission public."Admission"%ROWTYPE; a public."Admission"%ROWTYPE;
 r public."Reservation"%ROWTYPE; m public."HuroofMatch"%ROWTYPE; c public."HuroofCommandReceipt"%ROWTYPE;
 room public."HuroofRoom"%ROWTYPE; state_row public."HuroofCanonicalState"%ROWTYPE;
 policy_head public."HuroofIdentityPolicyHead"%ROWTYPE; policy_row public."HuroofIdentityPolicyRevision"%ROWTYPE;
 ptr public."ActiveCatalogPointer"%ROWTYPE; receipt public."CatalogValidationReceipt"%ROWTYPE; seal public."CatalogReleaseSeal"%ROWTYPE;
 profile_pointer public."HuroofContentPointer"%ROWTYPE; profile_revision public."HuroofContentRevision"%ROWTYPE; raw_profile public."HuroofRawArtifact"%ROWTYPE;
 profile JSONB; cfg JSONB; request_envelope JSONB; resolved_envelope JSONB; full_intent JSONB; intent_bytes BYTEA; intent_hash TEXT; request_hash TEXT;
 admission_id TEXT; reservation_id TEXT; match_id TEXT; event_id TEXT; reply JSONB; seq BIGINT; rev BIGINT;
 has_request BOOLEAN:=FALSE; has_logical BOOLEAN:=FALSE; derived JSONB; identity_project TEXT; lobby public."HuroofLobbyRevision"%ROWTYPE; snapshot JSONB; prepared_room JSONB; prepared_members JSONB; projection_item JSONB; projection_identity TEXT; projection_role TEXT; gameplay_snapshot public."HuroofRawArtifact"%ROWTYPE; gameplay_supplement public."HuroofRawArtifact"%ROWTYPE; gameplay_ref JSONB; gameplay_proof JSONB; gameplay_docs JSON; gameplay_root TEXT; category_id TEXT; category_doc JSON; category_label JSON; derived_categories JSONB:='[]'::JSONB;
BEGIN
 IF p_identity IS NULL OR p_request_key IS NULL OR p_request_key='' OR p_logical_match_id IS NULL OR p_logical_match_id='' OR jsonb_typeof(p_intent) IS DISTINCT FROM 'object' OR jsonb_typeof(p_initial) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'typed start request required'; END IF;
 -- No caller EXECUTE is granted until ENG03-03 supplies genuine service auth.
 -- This subject argument is never an authentication proof; no JSON/GUC flag substitutes for verified context.
 IF public.eng03_02_has_secret_key(p_intent) OR public.eng03_02_has_secret_key(p_initial) THEN RAISE EXCEPTION 'credential-shaped request material is not persistable'; END IF;
 IF p_intent->>'namespace' IS NULL OR p_intent->>'roomId' IS NULL OR p_intent->>'profileScope' IS NULL OR p_intent->>'policyRevision' IS NULL OR p_intent->>'policyHash' IS NULL OR p_intent->>'selectorVersion' IS NULL OR p_intent->>'admissionId' IS NULL OR p_intent->>'matchId' IS NULL THEN RAISE EXCEPTION 'complete canonical owner intent required'; END IF;
 IF (p_intent ? 'requestKey' AND p_intent->>'requestKey' IS DISTINCT FROM p_request_key) OR (p_intent ? 'logicalMatchId' AND p_intent->>'logicalMatchId' IS DISTINCT FROM p_logical_match_id) THEN RAISE EXCEPTION 'request identity disagrees with canonical intent'; END IF;
 IF (p_initial-ARRAY['config','configHash']::TEXT[])<>'{}'::JSONB OR p_initial->'config' IS NULL OR jsonb_typeof(p_initial->'config') IS DISTINCT FROM 'object' OR p_initial->>'configHash' IS NULL THEN RAISE EXCEPTION 'initial state must contain only the typed config and its hash'; END IF;
 IF jsonb_typeof(p_intent->'preparedRoom') IS DISTINCT FROM 'object' OR jsonb_typeof(p_intent->'preparedMembers') IS DISTINCT FROM 'array' OR jsonb_typeof(p_intent->'custody') IS DISTINCT FROM 'object' OR p_intent->>'lobbyRevision' !~ '^(0|[1-9][0-9]*)$' OR p_intent->>'lobbyStateHash' !~ '^[a-f0-9]{64}$' OR jsonb_typeof(p_projections) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'complete prepared lobby and verified custody required'; END IF;
 prepared_room:=p_intent->'preparedRoom'; prepared_members:=p_intent->'preparedMembers';
 SELECT n."firebaseProjectId" INTO identity_project FROM public."DeploymentNamespace" n JOIN public."FirebaseIdentity" i ON i."id"=p_identity AND i."firebaseProjectId"=n."firebaseProjectId" WHERE n."namespaceId"=p_intent->>'namespace';
 IF NOT FOUND THEN RAISE EXCEPTION 'identity namespace unavailable'; END IF;
 derived:=public.eng03_03_paid_identity(p_intent->>'namespace',identity_project,p_identity,p_intent->>'roomId',p_request_key);
 IF derived->>'admissionId' IS DISTINCT FROM p_intent->>'admissionId' OR derived->>'matchId' IS DISTINCT FROM p_intent->>'matchId' OR derived->>'logicalMatchId' IS DISTINCT FROM p_logical_match_id THEN RAISE EXCEPTION 'paid identity mismatch'; END IF;
 cfg:=p_initial->'config';
 IF public.eng03_02_has_secret_key(cfg) THEN RAISE EXCEPTION 'credential-shaped config is not persistable'; END IF;
 request_envelope:=jsonb_build_object('version',2,'identityId',p_identity,'requestKey',p_request_key,'logicalMatchId',p_logical_match_id,'intent',p_intent-'requestHash','initial',p_initial);
 request_hash:=public.int5b_hash_json(request_envelope);

 -- The shared wallet lock serializes new PG starts with the legacy reserve path.
 SELECT * INTO w FROM public."Wallet" WHERE "firebaseIdentityId"=p_identity FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'wallet unavailable'; END IF;
 SELECT * INTO request_admission FROM public."Admission" WHERE "firebaseIdentityId"=p_identity AND "requestKey"=p_request_key FOR UPDATE;
 has_request:=FOUND;
 SELECT * INTO logical_admission FROM public."Admission" WHERE "firebaseIdentityId"=p_identity AND "engine"='HUROOF' AND "logicalMatchId"=p_logical_match_id FOR UPDATE;
 has_logical:=FOUND;
 IF has_request AND has_logical AND request_admission."id"<>logical_admission."id" THEN RAISE EXCEPTION 'global request and logical-match keys resolve to distinct admissions'; END IF;
 IF has_request THEN a:=request_admission; ELSIF has_logical THEN a:=logical_admission; END IF;
 IF has_request OR has_logical THEN
  IF a."storageAuthority" IS DISTINCT FROM 'PG_HUROOF_V2' OR a."operation" IS DISTINCT FROM 'HOSTED_HUROOF_PG_V2' OR a."requestKey" IS DISTINCT FROM p_request_key OR a."logicalMatchId" IS DISTINCT FROM p_logical_match_id THEN RAISE EXCEPTION 'global legacy or cross-generation start collision'; END IF;
  IF a."requestHash" IS DISTINCT FROM request_hash OR a."state" IS DISTINCT FROM 'COMMITTED' THEN RAISE EXCEPTION 'complete canonical start intent conflicts with stored admission'; END IF;
  SELECT * INTO r FROM public."Reservation" WHERE "admissionId"=a."id" FOR UPDATE;
  IF NOT FOUND OR r."state" IS DISTINCT FROM 'COMMITTED' OR r."quantity"<>1 THEN RAISE EXCEPTION 'stored paid start lacks committed reservation'; END IF;
  SELECT * INTO m FROM public."HuroofMatch" WHERE "admissionId"=a."id";
  IF NOT FOUND OR m."ownerFirebaseIdentityId" IS DISTINCT FROM p_identity OR m."rawIntentHash" IS DISTINCT FROM encode(int4_crypto.digest(m."rawIntent",'sha256'),'hex') OR a."intentHash" IS DISTINCT FROM m."rawIntentHash" OR convert_from(m."rawIntent",'UTF8')::JSONB->'request' IS DISTINCT FROM request_envelope THEN RAISE EXCEPTION 'stored start identity or complete intent differs'; END IF;
  SELECT * INTO room FROM public."HuroofRoom" WHERE "namespace"=m."namespace" AND "id"=m."roomId" AND "ownerFirebaseIdentityId"=p_identity FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'current room owner authority required for saved replay'; END IF;
  SELECT * INTO c FROM public."HuroofCommandReceipt" WHERE "namespace"=m."namespace" AND "roomId"=m."roomId" AND "actorFirebaseIdentityId"=p_identity AND "requestKey"=p_request_key;
  IF NOT FOUND OR c."matchId" IS DISTINCT FROM m."id" OR c."intent" IS DISTINCT FROM m."rawIntent" OR c."intentHash" IS DISTINCT FROM m."rawIntentHash" OR c."outcomeHash" IS DISTINCT FROM encode(int4_crypto.digest(c."outcome",'sha256'),'hex') THEN RAISE EXCEPTION 'stored sealed command outcome is incomplete'; END IF;
  RETURN convert_from(c."outcome",'UTF8')::JSONB||jsonb_build_object('replayed',true);
 END IF;

 IF prepared_room ? 'challengeBridge' OR prepared_room ? 'challenge' OR (prepared_room ? 'activeQuestion' AND jsonb_typeof(prepared_room->'activeQuestion') NOT IN ('object','null')) OR (jsonb_typeof(prepared_room->'activeQuestion')='object' AND (prepared_room->'activeQuestion') ? 'challenge') THEN RAISE EXCEPTION 'fresh start bridge unavailable'; END IF;
 -- Challenge launch remains held until every required selector path is proved.
 IF COALESCE(cfg->'challenge','null'::JSONB)<>'null'::JSONB THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
 IF w."debt">0 OR w."available"<1 THEN RAISE EXCEPTION 'wallet cannot reserve'; END IF;
 SELECT * INTO identity_row FROM public."FirebaseIdentity" WHERE "id"=p_identity;
 SELECT * INTO namespace_row FROM public."DeploymentNamespace" WHERE "namespaceId"=p_intent->>'namespace';
 IF NOT FOUND OR identity_row."firebaseProjectId" IS DISTINCT FROM namespace_row."firebaseProjectId" THEN RAISE EXCEPTION 'current identity and namespace project do not match'; END IF;
 SELECT * INTO room FROM public."HuroofRoom" WHERE "namespace"=p_intent->>'namespace' AND "id"=p_intent->>'roomId' AND "ownerFirebaseIdentityId"=p_identity FOR UPDATE;
 IF NOT FOUND OR room."status" NOT IN ('SETUP','ACTIVE') THEN RAISE EXCEPTION 'owned room unavailable'; END IF;
 PERFORM public.eng03_03_lock_members(room."namespace",room."id");
 IF room."status" IS DISTINCT FROM 'SETUP' THEN RAISE EXCEPTION 'same-room successor unavailable'; END IF;
 IF jsonb_typeof(p_intent->'clientIntent') IS DISTINCT FROM 'object' OR ((p_intent->'clientIntent')-ARRAY['locator','intentId','profileScope','expectedRevision','offer']::TEXT[])<>'{}'::JSONB OR p_intent->'clientIntent'->>'intentId' IS DISTINCT FROM p_request_key OR p_intent->'clientIntent'->>'profileScope' IS DISTINCT FROM p_intent->>'profileScope' OR p_intent->'clientIntent'->>'expectedRevision' IS DISTINCT FROM p_intent->>'lobbyRevision' OR NOT EXISTS(SELECT 1 FROM public."HuroofLocator" l WHERE (l."namespace",l."roomId",l."generation")=(room."namespace",room."id",2) AND p_intent->'clientIntent'->>'locator'='M2-'||l."code") THEN RAISE EXCEPTION 'paid client intent mismatch'; END IF;
 SELECT * INTO lobby FROM public."HuroofLobbyRevision" WHERE "namespace"=room."namespace" AND "roomId"=room."id" ORDER BY "revision" DESC LIMIT 1;
 IF NOT FOUND OR lobby."revision"::TEXT IS DISTINCT FROM p_intent->>'lobbyRevision' OR lobby."stateHash" IS DISTINCT FROM p_intent->>'lobbyStateHash' OR public.int5b_hash_json(lobby."state") IS DISTINCT FROM lobby."stateHash" OR lobby."ownerFirebaseIdentityId" IS DISTINCT FROM p_identity OR lobby."roomGeneration" IS DISTINCT FROM room."generation" OR p_intent->>'roomGeneration' IS DISTINCT FROM room."generation"::TEXT OR prepared_room->>'revision' IS DISTINCT FROM (lobby."revision"+1)::TEXT OR prepared_room->>'roomCode' IS DISTINCT FROM lobby."state"->'room'->>'roomCode' OR prepared_room->'config' IS DISTINCT FROM cfg OR prepared_room->'manualParticipants' IS DISTINCT FROM lobby."state"->'room'->'manualParticipants' OR prepared_room->'questionCursor' IS DISTINCT FROM lobby."state"->'room'->'questionCursor' OR prepared_room->'game'->>'lifecycle' IS DISTINCT FROM 'ROUND_SETUP' OR jsonb_typeof(prepared_room->'game'->'board'->'cells') IS DISTINCT FROM 'array' OR jsonb_array_length(prepared_room->'game'->'board'->'cells')<>25 OR prepared_members IS DISTINCT FROM lobby."state"->'members' THEN RAISE EXCEPTION 'lobby preparation changed'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(lobby."state"->'memberBindings') AS b(value) LEFT JOIN public."HuroofMember" m ON (m."namespace",m."roomId",m."firebaseIdentityId")=(room."namespace",room."id",b.value->>'identityId') AND m."revokedAt" IS NULL WHERE m."firebaseIdentityId" IS NULL OR b.value->>'generation' IS DISTINCT FROM m."generation"::TEXT OR b.value->>'version' IS DISTINCT FROM m."version"::TEXT) OR (SELECT count(*) FROM public."HuroofMember" m WHERE m."namespace"=room."namespace" AND m."roomId"=room."id" AND m."revokedAt" IS NULL)<>jsonb_array_length(lobby."state"->'memberBindings') OR NOT EXISTS(SELECT 1 FROM public."HuroofMember" m WHERE (m."namespace",m."roomId",m."firebaseIdentityId",m."role")=(room."namespace",room."id",p_identity,'OWNER') AND m."revokedAt" IS NULL) THEN RAISE EXCEPTION 'lobby authority changed'; END IF;
 IF jsonb_array_length(COALESCE(prepared_room->'manualParticipants','[]'::JSONB))<>(SELECT count(*) FROM public."HuroofParticipant" pp WHERE pp."namespace"=room."namespace" AND pp."roomId"=room."id" AND pp."memberFirebaseIdentityId" IS NULL) OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(prepared_room->'manualParticipants','[]'::JSONB)) AS a(value) WHERE NOT EXISTS(SELECT 1 FROM public."HuroofParticipant" pp WHERE pp."namespace"=room."namespace" AND pp."roomId"=room."id" AND pp."memberFirebaseIdentityId" IS NULL AND pp."id"=a.value->>'id' AND pp."displayName"=a.value->>'displayName' AND pp."team"=a.value->>'team')) THEN RAISE EXCEPTION 'manual participants changed'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(prepared_members) AS m(value) WHERE m.value->>'role'='player' AND m.value->'active'='true'::JSONB AND m.value->'ready' IS DISTINCT FROM 'true'::JSONB) OR ((SELECT count(*) FROM jsonb_array_elements(prepared_members) AS m(value) WHERE m.value->>'role'='player' AND m.value->'active'='true'::JSONB)+jsonb_array_length(COALESCE(prepared_room->'manualParticipants','[]'::JSONB))>0 AND (NOT EXISTS(SELECT 1 FROM jsonb_array_elements(prepared_members) AS m(value) WHERE m.value->>'role'='player' AND m.value->'active'='true'::JSONB AND m.value->>'team'='horizontal') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(prepared_room->'manualParticipants','[]'::JSONB)) AS m(value) WHERE m.value->>'team'='horizontal') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(prepared_members) AS m(value) WHERE m.value->>'role'='player' AND m.value->'active'='true'::JSONB AND m.value->>'team'='vertical') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(prepared_room->'manualParticipants','[]'::JSONB)) AS m(value) WHERE m.value->>'team'='vertical'))) THEN RAISE EXCEPTION 'lobby teams not ready'; END IF;
 SELECT * INTO state_row FROM public."HuroofCanonicalState" WHERE "namespace"=room."namespace" AND "roomId"=room."id" FOR UPDATE;
 IF FOUND THEN RAISE EXCEPTION 'same-room successor unavailable'; ELSE seq:=1; rev:=lobby."revision"+1; END IF;
 PERFORM public.eng03_03_assert_current(room."namespace",p_identity,p_intent->>'policyRevision',p_intent->>'policyHash');
 SELECT * INTO policy_head FROM public."HuroofIdentityPolicyHead" WHERE "namespace"=room."namespace";
 IF NOT FOUND OR policy_head."revision"::TEXT IS DISTINCT FROM p_intent->>'policyRevision' OR policy_head."policyHash" IS DISTINCT FROM p_intent->>'policyHash' THEN RAISE EXCEPTION 'current identity policy unavailable or changed'; END IF;
 SELECT * INTO policy_row FROM public."HuroofIdentityPolicyRevision" WHERE "namespace"=room."namespace" AND "revision"=policy_head."revision" AND "policyHash"=policy_head."policyHash";
 IF NOT FOUND OR policy_row."firebaseProjectId" IS DISTINCT FROM namespace_row."firebaseProjectId" OR policy_row."issuer"='' OR jsonb_typeof(policy_row."audience") IS DISTINCT FROM 'object' OR encode(int4_crypto.digest(policy_row."rawPolicy",'sha256'),'hex') IS DISTINCT FROM policy_row."policyHash" THEN RAISE EXCEPTION 'immutable namespace identity policy is not internally consistent'; END IF;
 SELECT * INTO ptr FROM public."ActiveCatalogPointer" WHERE "id"='singleton' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'active catalog pointer unavailable'; END IF;
 SELECT * INTO receipt FROM public."CatalogValidationReceipt" WHERE "id"=ptr."validationReceiptId" AND "catalogReleaseId"=ptr."catalogReleaseId" AND "releaseRootHash"=ptr."releaseRootHash";
 IF NOT FOUND OR receipt."huroofProjectId" IS DISTINCT FROM namespace_row."firebaseProjectId" OR receipt."huroofReleaseId" IS DISTINCT FROM cfg->>'releaseId' OR receipt."huroofRootSha256" IS DISTINCT FROM cfg->>'releaseRootSha256' OR receipt."huroofCapabilityStateHash" IS NULL OR receipt."selectorVersion" IS DISTINCT FROM p_intent->>'selectorVersion' OR receipt."policyVersion" IS DISTINCT FROM p_intent->>'readinessPolicyVersion' THEN RAISE EXCEPTION 'active sealed receipt does not authorize this namespace/config/selector'; END IF;
  IF public.int5b_hash_json(cfg) IS DISTINCT FROM p_initial->>'configHash' OR cfg->'demo' IS DISTINCT FROM 'false'::JSONB OR cfg->'releaseDemoFixture' IS DISTINCT FROM 'false'::JSONB OR cfg ? 'qaAdmission' OR cfg ? 'paidAdmission' THEN RAISE EXCEPTION 'paid config is demo or does not satisfy the fixed schema'; END IF;
 SELECT * INTO seal FROM public."CatalogReleaseSeal" WHERE "catalogReleaseId"=receipt."catalogReleaseId" AND "releaseRootHash"=receipt."releaseRootHash" AND "sealHash"=receipt."sealHash";
 IF NOT FOUND THEN RAISE EXCEPTION 'receipt lacks its exact immutable release seal'; END IF;
 PERFORM public.eng03_03_lock_profile(room."namespace",p_intent->>'profileScope');
 SELECT * INTO profile_pointer FROM public."HuroofContentPointer" WHERE "namespace"=room."namespace" AND "kind"='profile' AND "scope"=p_intent->>'profileScope' AND "family"='profile';
 IF NOT FOUND THEN RAISE EXCEPTION 'selected profile pointer unavailable'; END IF;
 SELECT * INTO profile_revision FROM public."HuroofContentRevision" WHERE "namespace"=profile_pointer."namespace" AND "family"=profile_pointer."family" AND "sourceId"=profile_pointer."sourceId" AND "revision"=profile_pointer."revision" AND "rawArtifactHash"=profile_pointer."rawArtifactHash" AND "validationReceiptId"=receipt."id" AND "catalogReleaseId"=receipt."catalogReleaseId" AND "releaseRootHash"=receipt."releaseRootHash";
 IF NOT FOUND THEN RAISE EXCEPTION 'selected profile is not pinned to the active sealed receipt'; END IF;
 SELECT * INTO raw_profile FROM public."HuroofRawArtifact" WHERE "namespace"=profile_revision."namespace" AND "id"=profile_revision."rawArtifactId" AND "contentHash"=profile_revision."rawArtifactHash";
 IF NOT FOUND THEN RAISE EXCEPTION 'selected profile raw artifact unavailable'; END IF;
 profile:=convert_from(raw_profile."rawBytes",'UTF8')::JSONB;
 IF jsonb_typeof(profile) IS DISTINCT FROM 'object' OR raw_profile."contentHash" IS DISTINCT FROM profile_revision."rawArtifactHash" THEN RAISE EXCEPTION 'selected profile raw bytes/hash mismatch'; END IF;
 IF (raw_profile."serialization" LIKE 'huroof-gameplay-profile-%' OR profile->>'schemaVersion' LIKE 'huroof-gameplay-profile-%') AND (raw_profile."serialization" IS DISTINCT FROM 'huroof-gameplay-profile-v1' OR profile->>'schemaVersion' IS DISTINCT FROM 'huroof-gameplay-profile-v1') THEN RAISE EXCEPTION 'reserved gameplay profile unavailable'; END IF;
 IF raw_profile."serialization"='huroof-gameplay-profile-v1' AND COALESCE(profile->'challenge','null'::JSONB)<>'null'::JSONB THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
 IF raw_profile."serialization"='huroof-gameplay-profile-v1' THEN
  IF jsonb_typeof(profile) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile))<>18 OR NOT profile ?& ARRAY['schemaVersion','namespace','profileScope','sourceId','gameKind','mode','modality','categories','questionSeconds','opponentSeconds','mapPresentation','challenge','release','contentSnapshot','supplement','selector','readiness','custody'] THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF profile->>'schemaVersion' IS DISTINCT FROM 'huroof-gameplay-profile-v1' THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF profile->>'gameKind'='categories' THEN
   IF (lobby."state"->'room'->'config') ? 'categorySnapshot' OR NOT cfg ? 'categorySnapshot' OR (cfg-'categorySnapshot') IS DISTINCT FROM lobby."state"->'room'->'config' THEN RAISE EXCEPTION 'category config unavailable'; END IF;
  ELSIF cfg ? 'categorySnapshot' OR lobby."state"->'room'->'config' IS DISTINCT FROM cfg THEN RAISE EXCEPTION 'gameplay config unavailable'; END IF;
  IF jsonb_typeof(profile->'release') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'release'))<>7 OR NOT (profile->'release') ?& ARRAY['id','rootSha256','receiptId','catalogId','catalogRoot','sealHash','sourceManifestHash'] OR jsonb_typeof(profile->'selector') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'selector'))<>2 OR NOT (profile->'selector') ?& ARRAY['version','capabilityStateHash'] OR jsonb_typeof(profile->'readiness') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'readiness'))<>1 OR NOT (profile->'readiness') ? 'policyVersion' OR jsonb_typeof(profile->'custody') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(profile->'custody'))<>2 OR NOT (profile->'custody') ?& ARRAY['policyRevision','policyHash'] OR profile->'custody'->>'policyRevision' !~ '^[1-9][0-9]*$' OR profile->'custody'->>'policyHash' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF profile->'custody'->>'policyRevision' IS DISTINCT FROM p_intent->'custody'->>'authorityPolicyRevision' OR profile->'custody'->>'policyHash' IS DISTINCT FROM p_intent->'custody'->>'authorityPolicyHash' THEN RAISE EXCEPTION 'gameplay custody unavailable'; END IF;
  IF jsonb_typeof(cfg) IS DISTINCT FROM 'object' OR (cfg-ARRAY['demo','releaseDemoFixture','policyVersion','mapPresentation','gameKind','modality','mode','releaseId','releaseRootSha256','categories','teams','questionSeconds','opponentSeconds','labelledColours','difficulty','showQuestionOnAudience','challenge','categorySnapshot']::TEXT[])<>'{}'::JSONB THEN RAISE EXCEPTION 'gameplay config unavailable'; END IF;
  IF jsonb_typeof(cfg->'teams') IS DISTINCT FROM 'object' OR (cfg->'teams'-ARRAY['horizontal','vertical']::TEXT[])<>'{}'::JSONB OR NOT (cfg->'teams') ?& ARRAY['horizontal','vertical'] OR (cfg ? 'showQuestionOnAudience' AND jsonb_typeof(cfg->'showQuestionOnAudience') IS DISTINCT FROM 'boolean') THEN RAISE EXCEPTION 'gameplay config unavailable'; END IF;
  IF cfg->>'modality'='charades' AND COALESCE(cfg->'challenge','null'::JSONB)<>'null'::JSONB THEN RAISE EXCEPTION 'gameplay config unavailable'; END IF;
  IF COALESCE(cfg->'challenge','null'::JSONB)<>'null'::JSONB THEN
   IF jsonb_typeof(p_intent->'clientIntent'->'offer') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_intent->'clientIntent'->'offer'))<>3 OR NOT (p_intent->'clientIntent'->'offer') ?& ARRAY['protocolVersion','mechanics','definitionSchemas'] OR p_intent->'clientIntent'->'offer'->>'protocolVersion' IS DISTINCT FROM 't36-challenge-runtime-v1' OR jsonb_typeof(p_intent->'clientIntent'->'offer'->'mechanics') IS DISTINCT FROM 'array' OR jsonb_typeof(p_intent->'clientIntent'->'offer'->'definitionSchemas') IS DISTINCT FROM 'array' OR NOT (p_intent->'clientIntent'->'offer'->'mechanics') @> (cfg->'challenge'->'mechanics') OR NOT (p_intent->'clientIntent'->'offer'->'definitionSchemas') @> (cfg->'challenge'->'definitionSchemas') OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_intent->'clientIntent'->'offer'->'mechanics') x WHERE x NOT IN ('navigation','missing_tile','memory','qatar_map','word_search')) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_intent->'clientIntent'->'offer'->'definitionSchemas') x WHERE x NOT IN ('t36-challenge-definition-v1','t37-clean70-challenge-definition-v1','t37-topup-word-search-definition-v1')) OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(p_intent->'clientIntent'->'offer'->'mechanics') x)<>jsonb_array_length(p_intent->'clientIntent'->'offer'->'mechanics') OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(p_intent->'clientIntent'->'offer'->'definitionSchemas') x)<>jsonb_array_length(p_intent->'clientIntent'->'offer'->'definitionSchemas') THEN RAISE EXCEPTION 'client challenge capability unavailable'; END IF;
  END IF;

  IF cfg->>'mapPresentation'='interactive' AND (jsonb_typeof(cfg->'challenge'->'mechanics') IS DISTINCT FROM 'array' OR NOT (cfg->'challenge'->'mechanics') ? 'qatar_map') THEN RAISE EXCEPTION 'gameplay config unavailable'; END IF;
  IF cfg->>'gameKind' IS NULL OR cfg->>'gameKind' NOT IN ('huroof','categories') OR cfg->>'modality' IS NULL OR cfg->>'modality' NOT IN ('classic','image','video','charades') OR cfg->>'mapPresentation' IS NULL OR cfg->>'mapPresentation' NOT IN ('ordinary','interactive') OR (COALESCE(cfg->'challenge','null'::JSONB)<>'null'::JSONB AND (jsonb_typeof(cfg->'challenge') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(cfg->'challenge'))<>3 OR NOT (cfg->'challenge') ?& ARRAY['protocolVersion','mechanics','definitionSchemas'] OR cfg->'challenge'->>'protocolVersion' IS DISTINCT FROM 't36-challenge-runtime-v1' OR jsonb_typeof(cfg->'challenge'->'mechanics') IS DISTINCT FROM 'array' OR jsonb_typeof(cfg->'challenge'->'definitionSchemas') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg->'challenge'->'mechanics')<1 OR jsonb_array_length(cfg->'challenge'->'definitionSchemas')<1 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(cfg->'challenge'->'mechanics') m WHERE m NOT IN ('navigation','missing_tile','memory','qatar_map','word_search')) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(cfg->'challenge'->'definitionSchemas') s WHERE s NOT IN ('t36-challenge-definition-v1','t37-clean70-challenge-definition-v1','t37-topup-word-search-definition-v1')) OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(cfg->'challenge'->'mechanics') x)<>jsonb_array_length(cfg->'challenge'->'mechanics') OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(cfg->'challenge'->'definitionSchemas') x)<>jsonb_array_length(cfg->'challenge'->'definitionSchemas'))) THEN RAISE EXCEPTION 'gameplay config unavailable'; END IF;
  IF NOT public.int5b_valid_config((cfg-'challenge'-'categorySnapshot')||jsonb_build_object('gameKind','huroof','modality','classic','mapPresentation','ordinary')) THEN RAISE EXCEPTION 'gameplay config unavailable'; END IF;
  IF convert_from(raw_profile."rawBytes",'UTF8') IS DISTINCT FROM public.int5b_canonical_json(profile) OR profile->>'schemaVersion' IS DISTINCT FROM raw_profile."serialization" OR profile->>'namespace' IS DISTINCT FROM room."namespace" OR profile->>'profileScope' IS DISTINCT FROM profile_pointer."scope" OR profile->>'sourceId' IS DISTINCT FROM profile_revision."sourceId" OR profile->'gameKind' IS DISTINCT FROM cfg->'gameKind' OR profile->'mode' IS DISTINCT FROM cfg->'mode' OR profile->'modality' IS DISTINCT FROM cfg->'modality' OR profile->'mapPresentation' IS DISTINCT FROM cfg->'mapPresentation' OR profile->'categories' IS DISTINCT FROM cfg->'categories' OR profile->'questionSeconds' IS DISTINCT FROM cfg->'questionSeconds' OR profile->'opponentSeconds' IS DISTINCT FROM cfg->'opponentSeconds' OR profile->'challenge' IS DISTINCT FROM COALESCE(cfg->'challenge','null'::JSONB) OR profile->'release'->>'id' IS DISTINCT FROM receipt."huroofReleaseId" OR profile->'release'->>'rootSha256' IS DISTINCT FROM receipt."huroofRootSha256" OR profile->'release'->>'receiptId' IS DISTINCT FROM receipt."id" OR profile->'release'->>'catalogId' IS DISTINCT FROM receipt."catalogReleaseId" OR profile->'release'->>'catalogRoot' IS DISTINCT FROM receipt."releaseRootHash" OR profile->'release'->>'sealHash' IS DISTINCT FROM receipt."sealHash" OR profile->'release'->>'sourceManifestHash' IS DISTINCT FROM receipt."sourceEvidenceManifestHash" OR profile->'selector'->>'version' IS DISTINCT FROM receipt."selectorVersion" OR profile->'selector'->>'capabilityStateHash' IS DISTINCT FROM receipt."huroofCapabilityStateHash" OR profile->'readiness'->>'policyVersion' IS DISTINCT FROM receipt."policyVersion" OR octet_length(raw_profile."rawBytes")<>raw_profile."byteLength" OR encode(int4_crypto.digest(raw_profile."rawBytes",'sha256'),'hex') IS DISTINCT FROM raw_profile."contentHash" OR encode(int4_crypto.digest(raw_profile."provenanceBytes",'sha256'),'hex') IS DISTINCT FROM raw_profile."provenanceHash" THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  gameplay_ref:=profile->'contentSnapshot';
  IF jsonb_typeof(gameplay_ref) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(gameplay_ref))<>7 OR NOT gameplay_ref ?& ARRAY['namespace','id','hash','byteLength','mediaType','serialization','provenanceHash'] OR gameplay_ref->>'namespace' IS DISTINCT FROM room."namespace" OR gameplay_ref->>'mediaType' IS DISTINCT FROM 'application/json' OR gameplay_ref->>'serialization' IS DISTINCT FROM 'huroof-release-snapshot-v1' OR jsonb_typeof(gameplay_ref->'byteLength') IS DISTINCT FROM 'number' OR gameplay_ref->>'byteLength' !~ '^[1-9][0-9]{0,7}$' OR (gameplay_ref->>'byteLength')::NUMERIC>67108864 THEN RAISE EXCEPTION 'gameplay snapshot unavailable'; END IF;
  SELECT * INTO gameplay_snapshot FROM public."HuroofRawArtifact" WHERE ("namespace","id","contentHash","byteLength","mediaType","serialization","provenanceHash")=(room."namespace",gameplay_ref->>'id',gameplay_ref->>'hash',(gameplay_ref->>'byteLength')::BIGINT,gameplay_ref->>'mediaType',gameplay_ref->>'serialization',gameplay_ref->>'provenanceHash');
  IF NOT FOUND OR octet_length(gameplay_snapshot."rawBytes")<>gameplay_snapshot."byteLength" OR encode(int4_crypto.digest(gameplay_snapshot."rawBytes",'sha256'),'hex') IS DISTINCT FROM gameplay_snapshot."contentHash" OR encode(int4_crypto.digest(gameplay_snapshot."provenanceBytes",'sha256'),'hex') IS DISTINCT FROM gameplay_snapshot."provenanceHash" THEN RAISE EXCEPTION 'gameplay snapshot unavailable'; END IF;
  gameplay_docs:=convert_from(gameplay_snapshot."rawBytes",'UTF8')::JSON;
  IF json_typeof(gameplay_docs) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM json_each(gameplay_docs))<>3 OR (SELECT count(DISTINCT key) FROM json_each(gameplay_docs))<>3 OR EXISTS(SELECT 1 FROM json_each(gameplay_docs) WHERE key NOT IN ('schemaVersion','releaseId','documents')) OR gameplay_docs->>'schemaVersion' IS DISTINCT FROM 'huroof-release-snapshot-v1' OR gameplay_docs->>'releaseId' IS DISTINCT FROM receipt."huroofReleaseId" OR json_typeof(gameplay_docs->'documents') IS DISTINCT FROM 'array' OR json_array_length(gameplay_docs->'documents')>100000 OR EXISTS(SELECT 1 FROM json_array_elements(gameplay_docs->'documents') d WHERE json_typeof(d) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM json_each(d))<>2 OR (SELECT count(DISTINCT key) FROM json_each(d))<>2 OR EXISTS(SELECT 1 FROM json_each(d) WHERE key NOT IN ('path','data')) OR json_typeof(d->'path') IS DISTINCT FROM 'string' OR json_typeof(d->'data') IS DISTINCT FROM 'object' OR d->>'path' !~ ('^releases/'||receipt."huroofReleaseId"||'/(catalogCategories|questions|inventory)/[A-Za-z0-9_-]{1,120}$')) OR (SELECT count(*) FROM json_array_elements(gameplay_docs->'documents'))<>(SELECT count(DISTINCT d->>'path') FROM json_array_elements(gameplay_docs->'documents') d) THEN RAISE EXCEPTION 'gameplay snapshot unavailable'; END IF;
  SELECT '['||COALESCE(string_agg(d::TEXT,',' ORDER BY d->>'path' COLLATE "C"),'')||']' INTO gameplay_root FROM json_array_elements(gameplay_docs->'documents') d;
  IF encode(int4_crypto.digest(convert_to(gameplay_root,'UTF8'),'sha256'),'hex') IS DISTINCT FROM receipt."huroofRootSha256" THEN RAISE EXCEPTION 'gameplay snapshot unavailable'; END IF;
  IF profile->>'gameKind'='categories' THEN
   IF jsonb_typeof(profile->'categories') IS DISTINCT FROM 'array' OR jsonb_array_length(profile->'categories') NOT BETWEEN 2 AND 10 THEN RAISE EXCEPTION 'category snapshot unavailable'; END IF;
   FOR category_id IN SELECT jsonb_array_elements_text(profile->'categories') LOOP
    SELECT d INTO category_doc FROM json_array_elements(gameplay_docs->'documents') d WHERE d->>'path'='releases/'||receipt."huroofReleaseId"||'/catalogCategories/'||category_id;
    IF NOT FOUND OR json_typeof(category_doc->'data'->'id') IS DISTINCT FROM 'string' OR category_doc->'data'->>'id' IS DISTINCT FROM category_id OR (SELECT count(*) FROM json_each(category_doc->'data') e WHERE e.key='id')<>1 OR (SELECT count(*) FROM json_each(category_doc->'data') e WHERE e.key='labelAr')>1 OR (SELECT count(*) FROM json_each(category_doc->'data') e WHERE e.key='displayNameAr')>1 THEN RAISE EXCEPTION 'category snapshot unavailable'; END IF;
    category_label:=category_doc->'data'->'labelAr';
    IF category_label IS NULL OR json_typeof(category_label)='null' THEN category_label:=category_doc->'data'->'displayNameAr'; END IF;
    IF json_typeof(category_label) IS DISTINCT FROM 'string' OR translate(category_label #>> '{}',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF','')='' THEN RAISE EXCEPTION 'category snapshot unavailable'; END IF;
    derived_categories:=derived_categories||jsonb_build_array(jsonb_build_object('id',category_id,'labelAr',category_label #>> '{}'));
   END LOOP;
   IF cfg->'categorySnapshot' IS DISTINCT FROM derived_categories OR octet_length(convert_to(public.int5b_canonical_json(cfg),'UTF8'))>262144 OR octet_length(convert_to(public.int5b_canonical_json(prepared_room),'UTF8'))>262144 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_projections) p WHERE octet_length(convert_to(public.int5b_canonical_json(p),'UTF8'))>262144) THEN RAISE EXCEPTION 'category snapshot unavailable'; END IF;
  END IF;
  gameplay_proof:=convert_from(raw_profile."provenanceBytes",'UTF8')::JSONB;
  IF jsonb_typeof(gameplay_proof) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(gameplay_proof))<>8 OR NOT gameplay_proof ?& ARRAY['schemaVersion','namespace','profileScope','profileSourceId','contentHash','contentSnapshot','supplement','sourceManifestSha256'] THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  IF convert_from(raw_profile."provenanceBytes",'UTF8') IS DISTINCT FROM public.int5b_canonical_json(gameplay_proof) OR gameplay_proof->>'schemaVersion' IS DISTINCT FROM 'huroof-gameplay-profile-provenance-v1' OR gameplay_proof->>'namespace' IS DISTINCT FROM room."namespace" OR gameplay_proof->>'profileScope' IS DISTINCT FROM profile_pointer."scope" OR gameplay_proof->>'profileSourceId' IS DISTINCT FROM profile_revision."sourceId" OR gameplay_proof->>'contentHash' IS DISTINCT FROM raw_profile."contentHash" OR gameplay_proof->'contentSnapshot' IS DISTINCT FROM gameplay_ref OR gameplay_proof->'supplement' IS DISTINCT FROM profile->'supplement' OR gameplay_proof->>'sourceManifestSha256' IS DISTINCT FROM receipt."sourceEvidenceManifestHash" THEN RAISE EXCEPTION 'gameplay profile unavailable'; END IF;
  gameplay_ref:=profile->'supplement';
  IF gameplay_ref IS DISTINCT FROM 'null'::JSONB AND profile->'categories' ? 'tahadani-games-326' THEN RAISE EXCEPTION 'map supplier unavailable'; END IF;
  IF gameplay_ref='null'::JSONB AND (profile->'challenge' IS DISTINCT FROM 'null'::JSONB OR profile->>'mapPresentation' IS DISTINCT FROM 'ordinary') THEN RAISE EXCEPTION 'gameplay supplement unavailable'; END IF;
  IF gameplay_ref IS DISTINCT FROM 'null'::JSONB THEN
   IF gameplay_ref->>'serialization'='huroof-gameplay-map-supplement-v2' THEN RAISE EXCEPTION 'map supplier unavailable'; END IF;
   IF jsonb_typeof(gameplay_ref) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(gameplay_ref))<>7 OR NOT gameplay_ref ?& ARRAY['namespace','id','hash','byteLength','mediaType','serialization','provenanceHash'] OR gameplay_ref->>'namespace' IS DISTINCT FROM room."namespace" OR gameplay_ref->>'mediaType' IS DISTINCT FROM 'application/json' OR gameplay_ref->>'serialization' NOT IN ('huroof-gameplay-supplement-v1','huroof-gameplay-map-supplement-v2') OR jsonb_typeof(gameplay_ref->'byteLength') IS DISTINCT FROM 'number' OR gameplay_ref->>'byteLength' !~ '^[1-9][0-9]{0,7}$' OR (gameplay_ref->>'byteLength')::NUMERIC>67108864 THEN RAISE EXCEPTION 'gameplay supplement unavailable'; END IF;
   SELECT * INTO gameplay_supplement FROM public."HuroofRawArtifact" WHERE ("namespace","id","contentHash","byteLength","mediaType","serialization","provenanceHash")=(room."namespace",gameplay_ref->>'id',gameplay_ref->>'hash',(gameplay_ref->>'byteLength')::BIGINT,gameplay_ref->>'mediaType',gameplay_ref->>'serialization',gameplay_ref->>'provenanceHash');
   IF NOT FOUND OR octet_length(gameplay_supplement."rawBytes")<>gameplay_supplement."byteLength" OR encode(int4_crypto.digest(gameplay_supplement."rawBytes",'sha256'),'hex') IS DISTINCT FROM gameplay_supplement."contentHash" OR encode(int4_crypto.digest(gameplay_supplement."provenanceBytes",'sha256'),'hex') IS DISTINCT FROM gameplay_supplement."provenanceHash" THEN RAISE EXCEPTION 'gameplay supplement unavailable'; END IF;
   gameplay_proof:=convert_from(gameplay_supplement."provenanceBytes",'UTF8')::JSONB;
   IF convert_from(gameplay_supplement."provenanceBytes",'UTF8') IS DISTINCT FROM public.int5b_canonical_json(gameplay_proof) OR jsonb_typeof(gameplay_proof) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(gameplay_proof))<>10 OR NOT gameplay_proof ?& ARRAY['schemaVersion','namespace','profileScope','profileSourceId','releaseId','releaseRootSha256','receiptId','sourceManifestSha256','contentHash','contentSnapshot'] OR gameplay_proof->>'schemaVersion' IS DISTINCT FROM 'huroof-gameplay-supplement-provenance-v1' OR gameplay_proof->>'namespace' IS DISTINCT FROM room."namespace" OR gameplay_proof->>'profileScope' IS DISTINCT FROM profile_pointer."scope" OR gameplay_proof->>'profileSourceId' IS DISTINCT FROM profile_revision."sourceId" OR gameplay_proof->>'releaseId' IS DISTINCT FROM receipt."huroofReleaseId" OR gameplay_proof->>'releaseRootSha256' IS DISTINCT FROM receipt."huroofRootSha256" OR gameplay_proof->>'receiptId' IS DISTINCT FROM receipt."id" OR gameplay_proof->>'sourceManifestSha256' IS DISTINCT FROM receipt."sourceEvidenceManifestHash" OR gameplay_proof->>'contentHash' IS DISTINCT FROM gameplay_supplement."contentHash" OR gameplay_proof->'contentSnapshot' IS DISTINCT FROM profile->'contentSnapshot' THEN RAISE EXCEPTION 'gameplay supplement unavailable'; END IF;
  END IF;
 ELSE
  IF lobby."state"->'room'->'config' IS DISTINCT FROM cfg THEN RAISE EXCEPTION 'legacy config unavailable'; END IF;
  IF NOT public.int5b_valid_config(cfg) THEN RAISE EXCEPTION 'legacy config unavailable'; END IF;
 END IF;
 IF p_intent ? 'config' AND p_intent->'config' IS DISTINCT FROM cfg OR p_intent ? 'configHash' AND p_intent->>'configHash' IS DISTINCT FROM p_initial->>'configHash' THEN RAISE EXCEPTION 'canonical intent config differs from charged config'; END IF;
 resolved_envelope:=jsonb_build_object('namespace',room."namespace",'roomId',room."id",'ownerFirebaseIdentityId',p_identity,'admissionId',p_intent->>'admissionId','matchId',p_intent->>'matchId','firebaseProjectId',namespace_row."firebaseProjectId",'policyRevision',policy_row."revision",'policyHash',policy_row."policyHash",'profileScope',profile_pointer."scope",'profileFamily',profile_revision."family",'profileSourceId',profile_revision."sourceId",'profileRevision',profile_revision."revision",'profileRawArtifactId',raw_profile."id",'profileRawArtifactHash',raw_profile."contentHash",'validationReceiptId',receipt."id",'catalogReleaseId',receipt."catalogReleaseId",'releaseRootHash',receipt."releaseRootHash",'catalogSealHash',receipt."sealHash",'sourceRef',receipt."sourceEvidenceManifestHash",'rawRefs',jsonb_build_object('profileId',raw_profile."id",'profileHash',raw_profile."contentHash"),'selector',jsonb_build_object('selectorVersion',receipt."selectorVersion",'capabilityStateHash',receipt."huroofCapabilityStateHash"),'selectorVersion',receipt."selectorVersion",'readinessPolicyVersion',receipt."policyVersion",'config',cfg,'configHash',p_initial->>'configHash');
 full_intent:=jsonb_build_object('request',request_envelope,'resolved',resolved_envelope);
 intent_bytes:=convert_to(full_intent::TEXT,'UTF8');
 intent_hash:=encode(int4_crypto.digest(intent_bytes,'sha256'),'hex');
 admission_id:=p_intent->>'admissionId'; match_id:=p_intent->>'matchId'; reservation_id:=admission_id||':reservation';
 IF admission_id !~ '^[A-Za-z0-9._:-]{1,200}$' OR match_id !~ '^[A-Za-z0-9._:-]{1,200}$' THEN RAISE EXCEPTION 'stable source ids required'; END IF;
 event_id:=encode(int4_crypto.digest(convert_to(room."namespace"||':'||room."id"||':'||match_id||':STARTED','UTF8'),'sha256'),'hex');

 PERFORM public.eng03_03_custody_assert(room."namespace",namespace_row."firebaseProjectId",p_identity,room."id",room."generation",p_intent->>'profileScope',NULL,p_intent->>'policyRevision',p_intent->>'policyHash',p_intent->'custody');
 INSERT INTO public."Admission"("id","firebaseIdentityId","walletId","engine","operation","mode","logicalMatchId","requestKey","requestHash","intentHash","requestVersion","selectorVersion","state","version","storageAuthority","updatedAt")
 VALUES(admission_id,p_identity,w."id",'HUROOF','HOSTED_HUROOF_PG_V2','CLASSIC',p_logical_match_id,p_request_key,request_hash,intent_hash,2,receipt."selectorVersion",'HELD',0,'PG_HUROOF_V2',clock_timestamp());
 INSERT INTO public."Reservation"("id","admissionId","quantity","state","updatedAt") VALUES(reservation_id,admission_id,1,'HELD',clock_timestamp());
 INSERT INTO public."WalletEntry"("id","walletId","sequence","originType","originId","effect","reservationId","deltaAvailable","deltaHeld","deltaDebt","resultingAvailable","resultingHeld","resultingDebt","actorFirebaseIdentityId") VALUES(admission_id||':reserve',w."id",w."version"+1,'ADMISSION',admission_id,'RESERVE',reservation_id,-1,1,0,w."available"-1,w."held"+1,w."debt",p_identity);
 UPDATE public."Wallet" SET "available"="available"-1,"held"="held"+1,"version"="version"+1,"updatedAt"=clock_timestamp() WHERE "id"=w."id";
 INSERT INTO public."HuroofMatch"("namespace","id","roomId","ownerFirebaseIdentityId","admissionId","profile","profileRawArtifactId","profileHash","config","configHash","rawIntent","rawIntentHash","policyRevision","policyHash","state") VALUES(room."namespace",match_id,room."id",p_identity,admission_id,profile,raw_profile."id",raw_profile."contentHash",cfg,p_initial->>'configHash',intent_bytes,intent_hash,policy_head."revision",policy_head."policyHash",'STARTED');
 UPDATE public."HuroofMatch" SET "state"='ACTIVE',"version"="version"+1 WHERE ("namespace","id")=(room."namespace",match_id);
 INSERT INTO public."HuroofMatchPin"("namespace","matchId","profileScope","validationReceiptId","catalogReleaseId","releaseRootHash","profileFamily","profileSourceId","profileRevision","profileRawArtifactId","profileRawArtifactHash","catalogSealHash","sourceRef","rawRefs","selector","config","profile") VALUES(room."namespace",match_id,p_intent->>'profileScope',receipt."id",receipt."catalogReleaseId",receipt."releaseRootHash",profile_revision."family",profile_revision."sourceId",profile_revision."revision",profile_revision."rawArtifactId",profile_revision."rawArtifactHash",receipt."sealHash",receipt."sourceEvidenceManifestHash",jsonb_build_object('profileId',profile_revision."rawArtifactId",'profileHash',profile_revision."rawArtifactHash"),jsonb_build_object('selectorVersion',receipt."selectorVersion",'capabilityStateHash',receipt."huroofCapabilityStateHash"),cfg,profile);
 reply:=jsonb_build_object('admissionId',admission_id,'matchId',match_id,'roomId',room."id",'status','STARTED','state','COMMITTED','revision',rev,'sequence',seq,'replayed',false);
 INSERT INTO public."HuroofCommandReceipt"("namespace","roomId","actorFirebaseIdentityId","requestKey","matchId","intent","intentHash","outcome","outcomeHash","resultingRevision","resultingSequence") VALUES(room."namespace",room."id",p_identity,p_request_key,match_id,intent_bytes,intent_hash,convert_to(reply::TEXT,'UTF8'),encode(int4_crypto.digest(convert_to(reply::TEXT,'UTF8'),'sha256'),'hex'),rev,seq);
 INSERT INTO public."HuroofCanonicalState"("namespace","roomId","ownerFirebaseIdentityId","activeMatchId","status","revision","sequence","privateState") VALUES(room."namespace",room."id",p_identity,match_id,'ACTIVE',rev,seq,jsonb_build_object('room',prepared_room,'members',prepared_members,'currentResult',NULL,'lastResult',NULL)) ON CONFLICT("namespace","roomId") DO UPDATE SET "activeMatchId"=EXCLUDED."activeMatchId","status"='ACTIVE',"revision"=EXCLUDED."revision","sequence"=EXCLUDED."sequence","privateState"=EXCLUDED."privateState","updatedAt"=clock_timestamp();
 UPDATE public."HuroofRoom" SET "status"='ACTIVE',"version"="version"+1,"updatedAt"=clock_timestamp() WHERE "namespace"=room."namespace" AND "id"=room."id";
 INSERT INTO public."HuroofEvent"("namespace","roomId","sequence","id","matchId","actorFirebaseIdentityId","requestKey","revision","eventType") VALUES(room."namespace",room."id",seq,event_id,match_id,p_identity,p_request_key,rev,'STARTED');
 INSERT INTO public."HuroofProjection"("namespace","roomId","audience","scope","revision","throughSequence","authGeneration","payload") VALUES(room."namespace",room."id",'PUBLIC','public',rev,seq,room."generation",jsonb_build_object('status','ACTIVE','revision',rev)) ON CONFLICT("namespace","roomId","audience","scope") DO UPDATE SET "revision"=EXCLUDED."revision","throughSequence"=EXCLUDED."throughSequence","authGeneration"=EXCLUDED."authGeneration","payload"=EXCLUDED."payload","updatedAt"=clock_timestamp();
 IF jsonb_array_length(p_projections)<>(SELECT count(*) FROM public."HuroofMember" mm WHERE mm."namespace"=room."namespace" AND mm."roomId"=room."id" AND mm."revokedAt" IS NULL) OR (SELECT count(DISTINCT value->>'uid') FROM jsonb_array_elements(p_projections))<>jsonb_array_length(p_projections) THEN RAISE EXCEPTION 'projection scope mismatch'; END IF;
 FOR projection_item IN SELECT value FROM jsonb_array_elements(p_projections) LOOP
  SELECT fi."id" INTO projection_identity FROM public."FirebaseIdentity" fi JOIN public."HuroofMember" mm ON mm."firebaseIdentityId"=fi."id" AND mm."namespace"=room."namespace" AND mm."roomId"=room."id" AND mm."revokedAt" IS NULL WHERE fi."firebaseProjectId"=namespace_row."firebaseProjectId" AND fi."firebaseUid"=projection_item->>'uid';
  IF NOT FOUND THEN RAISE EXCEPTION 'projection scope invalid'; END IF;
  SELECT mm.value->>'role' INTO projection_role FROM jsonb_array_elements(prepared_members) AS mm(value) WHERE mm.value->>'uid'=projection_item->>'uid' AND mm.value->'active'='true'::JSONB;
  IF NOT FOUND OR projection_role NOT IN ('host','player','audience') OR projection_item->'payload'->>'role' IS DISTINCT FROM projection_role OR projection_item->'payload'->>'revision' IS DISTINCT FROM rev::TEXT OR NOT public.eng03_03_projection_safe(projection_item->'payload',projection_identity=p_identity) THEN RAISE EXCEPTION 'projection scope invalid'; END IF;
  INSERT INTO public."HuroofProjection"("namespace","roomId","audience","scope","revision","throughSequence","authGeneration","payload") VALUES(room."namespace",room."id",CASE WHEN projection_identity=p_identity THEN 'OWNER' ELSE 'MEMBER' END,projection_identity,rev,seq,room."generation",projection_item->'payload');
 END LOOP;
 INSERT INTO public."HuroofRealtimeOutbox"("namespace","roomId","sequence","eventId") VALUES(room."namespace",room."id",seq,event_id);
 INSERT INTO public."HuroofOutboxDelivery"("namespace","roomId","sequence") VALUES(room."namespace",room."id",seq);
 INSERT INTO public."WalletEntry"("id","walletId","sequence","originType","originId","effect","reservationId","deltaAvailable","deltaHeld","deltaDebt","resultingAvailable","resultingHeld","resultingDebt","actorFirebaseIdentityId") VALUES(admission_id||':commit',w."id",w."version"+2,'ADMISSION',admission_id,'COMMIT',reservation_id,0,-1,0,w."available"-1,w."held",w."debt",p_identity);
 UPDATE public."Wallet" SET "held"="held"-1,"version"="version"+1,"updatedAt"=clock_timestamp() WHERE "id"=w."id";
 UPDATE public."Admission" SET "state"='COMMITTED',"version"=1,"updatedAt"=clock_timestamp() WHERE "id"=admission_id;
 UPDATE public."Reservation" SET "state"='COMMITTED',"committedAt"=clock_timestamp(),"updatedAt"=clock_timestamp() WHERE "id"=reservation_id;
 RETURN reply;
END $$;

CREATE OR REPLACE FUNCTION public.eng03_03_setup_create(p_namespace TEXT,p_identity TEXT,p_revision TEXT,p_hash TEXT,p_key TEXT,p_intent JSONB,p_state JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE project TEXT; uid TEXT; derived JSONB; room_id TEXT; code TEXT; prior public."HuroofLobbyRevision"%ROWTYPE; intent_bytes BYTEA; outcome JSONB; outcome_bytes BYTEA;
BEGIN
 SELECT n."firebaseProjectId",i."firebaseUid" INTO project,uid FROM public."DeploymentNamespace" n JOIN public."FirebaseIdentity" i ON i."id"=p_identity AND i."firebaseProjectId"=n."firebaseProjectId" WHERE n."namespaceId"=p_namespace;
 IF NOT FOUND OR jsonb_typeof(p_intent) IS DISTINCT FROM 'object' OR p_intent->>'type' IS DISTINCT FROM 'CREATE_ROOM' OR p_intent->>'intentId' IS DISTINCT FROM p_key OR p_key !~ '^[A-Za-z0-9_-]{1,120}$' OR (p_intent-ARRAY['type','intentId','config','displayName']::TEXT[])<>'{}'::JSONB THEN RAISE EXCEPTION 'invalid create intent'; END IF;
 derived:=public.eng03_03_create_identity(p_namespace,project,p_identity,p_key); room_id:=derived->>'roomId'; code:=derived->>'code';
 PERFORM public.eng03_03_assert_current(p_namespace,p_identity,p_revision,p_hash);
 SELECT l.* INTO prior FROM public."HuroofLobbyRevision" l JOIN public."HuroofRoom" r ON (r."namespace",r."id",r."ownerFirebaseIdentityId")=(l."namespace",l."roomId",l."ownerFirebaseIdentityId") WHERE (l."namespace",l."roomId",l."actorFirebaseIdentityId",l."requestKey")=(p_namespace,room_id,p_identity,p_key) AND r."ownerFirebaseIdentityId"=p_identity;
 IF FOUND THEN
  IF convert_from(prior."intent",'UTF8')::JSONB IS DISTINCT FROM p_intent OR prior."outcomeHash" IS DISTINCT FROM encode(int4_crypto.digest(prior."outcome",'sha256'),'hex') THEN RAISE EXCEPTION 'create intent conflict'; END IF;
  RETURN convert_from(prior."outcome",'UTF8')::JSONB||jsonb_build_object('replayed',true);
 END IF;
 PERFORM public.eng03_03_assert_current(p_namespace,p_identity,p_revision,p_hash);
 IF (p_state->'room') ? 'challengeBridge' OR (p_state->'room') ? 'challenge' OR ((p_state->'room') ? 'activeQuestion' AND jsonb_typeof(p_state->'room'->'activeQuestion') NOT IN ('object','null')) OR (jsonb_typeof(p_state->'room'->'activeQuestion')='object' AND (p_state->'room'->'activeQuestion') ? 'challenge') THEN RAISE EXCEPTION 'fresh setup bridge unavailable'; END IF;
 IF public.eng03_02_has_secret_key(p_intent) OR public.eng03_02_has_secret_key(p_state) OR NOT public.int5b_valid_config(p_state->'room'->'config') OR p_state->'room'->'config'->>'mode' IS DISTINCT FROM 'classic' OR p_state->'room'->'config'->>'difficulty' IS DISTINCT FROM 'mixed' OR p_state->'members'->0->'ready' IS DISTINCT FROM 'true'::JSONB OR jsonb_array_length(COALESCE(p_state->'room'->'manualParticipants','[]'::JSONB))<>0 OR jsonb_typeof(p_state) IS DISTINCT FROM 'object' OR p_state->'room'->'config' IS DISTINCT FROM p_intent->'config' OR p_state->'room'->>'roomCode' IS DISTINCT FROM code OR p_state->'room'->>'revision' IS DISTINCT FROM '0' OR jsonb_array_length(p_state->'members')<>1 OR p_state->'members'->0->>'uid' IS DISTINCT FROM uid OR p_state->'members'->0->>'displayName' IS DISTINCT FROM p_intent->>'displayName' OR p_state->'members'->0->>'role' IS DISTINCT FROM 'host' THEN RAISE EXCEPTION 'invalid create state'; END IF;
 INSERT INTO public."HuroofRoom"("namespace","id","ownerFirebaseIdentityId") VALUES(p_namespace,room_id,p_identity);
 INSERT INTO public."HuroofLocator"("namespace","code","roomId","generation") VALUES(p_namespace,code,room_id,2);
 INSERT INTO public."HuroofMember"("namespace","roomId","firebaseIdentityId","role") VALUES(p_namespace,room_id,p_identity,'OWNER');
 intent_bytes:=convert_to(p_intent::TEXT,'UTF8'); outcome:=jsonb_build_object('roomId',room_id,'locator','M2-'||code,'revision',0,'replayed',false); outcome_bytes:=convert_to(outcome::TEXT,'UTF8');
 INSERT INTO public."HuroofLobbyRevision"("namespace","roomId","ownerFirebaseIdentityId","revision","roomGeneration","actorFirebaseIdentityId","requestKey","intent","intentHash","outcome","outcomeHash","state","stateHash") VALUES(p_namespace,room_id,p_identity,0,1,p_identity,p_key,intent_bytes,encode(int4_crypto.digest(intent_bytes,'sha256'),'hex'),outcome_bytes,encode(int4_crypto.digest(outcome_bytes,'sha256'),'hex'),p_state,public.int5b_hash_json(p_state));
 RETURN outcome;
END $$;

CREATE OR REPLACE FUNCTION public.eng03_03_lobby_commit(p_namespace TEXT,p_identity TEXT,p_room TEXT,p_generation BIGINT,p_revision BIGINT,p_policy_revision TEXT,p_policy_hash TEXT,p_intent JSONB,p_state JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE room public."HuroofRoom"%ROWTYPE; member public."HuroofMember"%ROWTYPE; lobby public."HuroofLobbyRevision"%ROWTYPE; saved public."HuroofLobbyRevision"%ROWTYPE; uid TEXT; intent_type TEXT; key TEXT; expected JSONB; payload JSONB; item JSONB; target_uid TEXT; target_id TEXT; target_team TEXT; new_id TEXT; ord INTEGER; horizontal INTEGER; vertical INTEGER; role TEXT; name TEXT; raw BYTEA; outcome JSONB; outcome_bytes BYTEA;
BEGIN
 PERFORM public.eng03_03_lock_room(p_namespace,p_room);
 PERFORM public.eng03_03_lock_members(p_namespace,p_room);
 SELECT * INTO room FROM public."HuroofRoom" WHERE ("namespace","id")=(p_namespace,p_room);
 SELECT i."firebaseUid" INTO uid FROM public."FirebaseIdentity" i JOIN public."DeploymentNamespace" n ON n."namespaceId"=p_namespace AND n."firebaseProjectId"=i."firebaseProjectId" WHERE i."id"=p_identity;
 IF NOT FOUND OR jsonb_typeof(p_intent) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'lobby identity unavailable'; END IF;
 key:=p_intent->>'intentId'; intent_type:=p_intent->>'type'; payload:=p_intent->'payload';
 IF key IS NULL OR key !~ '^[A-Za-z0-9_-]{1,120}$' OR jsonb_typeof(payload) IS DISTINCT FROM 'object' OR (p_intent-ARRAY['type','intentId','expectedRevision','payload']::TEXT[])<>'{}'::JSONB OR public.eng03_02_has_secret_key(p_intent) OR public.eng03_02_has_secret_key(p_state) THEN RAISE EXCEPTION 'invalid lobby intent'; END IF;
 PERFORM public.eng03_03_assert_current(p_namespace,p_identity,p_policy_revision,p_policy_hash);
 SELECT * INTO saved FROM public."HuroofLobbyRevision" WHERE ("namespace","roomId","actorFirebaseIdentityId","requestKey")=(p_namespace,p_room,p_identity,key);
 IF FOUND THEN IF convert_from(saved."intent",'UTF8')::JSONB IS DISTINCT FROM p_intent OR saved."outcomeHash" IS DISTINCT FROM encode(int4_crypto.digest(saved."outcome",'sha256'),'hex') THEN RAISE EXCEPTION 'lobby intent conflict'; END IF; RETURN jsonb_build_object('roomId',p_room,'revision',saved."revision",'replayed',true); END IF;
 PERFORM public.eng03_03_assert_current(p_namespace,p_identity,p_policy_revision,p_policy_hash);
 IF room."status"<>'SETUP' OR room."generation"<>p_generation THEN RAISE EXCEPTION 'lobby unavailable'; END IF;
 SELECT * INTO lobby FROM public."HuroofLobbyRevision" WHERE ("namespace","roomId")=(p_namespace,p_room) ORDER BY "revision" DESC LIMIT 1;
 IF NOT FOUND OR lobby."revision"<>p_revision OR p_intent->>'expectedRevision' IS DISTINCT FROM p_revision::TEXT OR lobby."stateHash" IS DISTINCT FROM public.int5b_hash_json(lobby."state") THEN RAISE EXCEPTION 'stale lobby'; END IF;
 IF (lobby."state"->'room') ? 'challengeBridge' AND (jsonb_typeof(lobby."state"->'room'->'challengeBridge') IS DISTINCT FROM 'object' OR jsonb_typeof(lobby."state"->'room'->'challengeBridge'->'activeOccurrence') IS DISTINCT FROM 'string' OR jsonb_typeof(lobby."state"->'room'->'challengeBridge'->'selectedCellId') IS DISTINCT FROM 'string' OR lobby."state"->'room'->'challengeBridge'->'applied' IS DISTINCT FROM '{}'::JSONB OR ((lobby."state"->'room'->'challengeBridge') ? 'appliedEncoding' AND (lobby."state"->'room'->'challengeBridge'->>'appliedEncoding' IS DISTINCT FROM 'utf8-hex-v1' OR (lobby."state"->'room'->'challengeBridge'-ARRAY['activeOccurrence','selectedCellId','appliedEncoding','applied']::TEXT[])<>'{}'::JSONB)) OR (NOT (lobby."state"->'room'->'challengeBridge') ? 'appliedEncoding' AND (lobby."state"->'room'->'challengeBridge'-ARRAY['activeOccurrence','selectedCellId','applied']::TEXT[])<>'{}'::JSONB)) THEN RAISE EXCEPTION 'lobby bridge unavailable'; END IF;
 expected:=jsonb_set(lobby."state",'{room,revision}',to_jsonb(p_revision+1));
 IF jsonb_typeof(expected->'room'->'challengeBridge')='object' AND NOT (expected->'room'->'challengeBridge') ? 'appliedEncoding' AND (expected->'room'->'challengeBridge'-ARRAY['activeOccurrence','selectedCellId','applied']::TEXT[])='{}'::JSONB AND expected->'room'->'challengeBridge'->'applied'='{}'::JSONB THEN expected:=jsonb_set(expected,'{room,challengeBridge,appliedEncoding}','"utf8-hex-v1"'::JSONB); END IF;
 SELECT * INTO member FROM public."HuroofMember" WHERE ("namespace","roomId","firebaseIdentityId")=(p_namespace,p_room,p_identity);
 IF intent_type='JOIN_ROOM' THEN
  IF FOUND OR (payload-ARRAY['role','displayName','offer']::TEXT[])<>'{}'::JSONB OR payload->>'role' NOT IN ('player','audience') OR length(btrim(payload->>'displayName')) NOT BETWEEN 1 AND 48 OR payload->>'displayName' ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'join unavailable'; END IF;
  IF payload ? 'offer' AND payload->'offer'<>'null'::JSONB AND (jsonb_typeof(payload->'offer') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(payload->'offer'))<>3 OR NOT (payload->'offer') ?& ARRAY['protocolVersion','mechanics','definitionSchemas'] OR payload->'offer'->>'protocolVersion' IS DISTINCT FROM 't36-challenge-runtime-v1' OR jsonb_typeof(payload->'offer'->'mechanics') IS DISTINCT FROM 'array' OR jsonb_typeof(payload->'offer'->'definitionSchemas') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'offer'->'mechanics') NOT BETWEEN 1 AND 5 OR jsonb_array_length(payload->'offer'->'definitionSchemas') NOT BETWEEN 1 AND 3 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(payload->'offer'->'mechanics') x WHERE x NOT IN ('navigation','missing_tile','memory','qatar_map','word_search')) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(payload->'offer'->'definitionSchemas') x WHERE x NOT IN ('t36-challenge-definition-v1','t37-clean70-challenge-definition-v1','t37-topup-word-search-definition-v1')) OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(payload->'offer'->'mechanics') x)<>jsonb_array_length(payload->'offer'->'mechanics') OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(payload->'offer'->'definitionSchemas') x)<>jsonb_array_length(payload->'offer'->'definitionSchemas')) THEN RAISE EXCEPTION 'client challenge capability unavailable'; END IF;
  IF COALESCE(lobby."state"->'room'->'config'->'challenge','null'::JSONB)<>'null'::JSONB THEN
   IF jsonb_typeof(payload->'offer') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(payload->'offer'))<>3 OR NOT (payload->'offer') ?& ARRAY['protocolVersion','mechanics','definitionSchemas'] OR payload->'offer'->>'protocolVersion' IS DISTINCT FROM 't36-challenge-runtime-v1' OR jsonb_typeof(payload->'offer'->'mechanics') IS DISTINCT FROM 'array' OR jsonb_typeof(payload->'offer'->'definitionSchemas') IS DISTINCT FROM 'array' OR NOT (payload->'offer'->'mechanics') @> (lobby."state"->'room'->'config'->'challenge'->'mechanics') OR NOT (payload->'offer'->'definitionSchemas') @> (lobby."state"->'room'->'config'->'challenge'->'definitionSchemas') OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(payload->'offer'->'mechanics') x WHERE x NOT IN ('navigation','missing_tile','memory','qatar_map','word_search')) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(payload->'offer'->'definitionSchemas') x WHERE x NOT IN ('t36-challenge-definition-v1','t37-clean70-challenge-definition-v1','t37-topup-word-search-definition-v1')) OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(payload->'offer'->'mechanics') x)<>jsonb_array_length(payload->'offer'->'mechanics') OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(payload->'offer'->'definitionSchemas') x)<>jsonb_array_length(payload->'offer'->'definitionSchemas') THEN RAISE EXCEPTION 'client challenge capability unavailable'; END IF;
  END IF;
  role:=payload->>'role'; name:=payload->>'displayName';
  item:=jsonb_build_object('uid',uid,'role',role,'displayName',name,'ready',false,'active',true);
  IF role='player' THEN
   SELECT count(*) FILTER(WHERE v.value->>'team'='horizontal'),count(*) FILTER(WHERE v.value->>'team'='vertical') INTO horizontal,vertical FROM (SELECT value FROM jsonb_array_elements(lobby."state"->'members') WHERE value->>'role'='player' AND value->'active'='true'::JSONB UNION ALL SELECT value FROM jsonb_array_elements(COALESCE(lobby."state"->'room'->'manualParticipants','[]'::JSONB))) v;
   target_team:=CASE WHEN horizontal<=vertical THEN 'horizontal' ELSE 'vertical' END; item:=item||jsonb_build_object('team',target_team);
  END IF;
  expected:=jsonb_set(expected,'{members}',(expected->'members')||jsonb_build_array(item));
  expected:=jsonb_set(expected,'{memberBindings}',(expected->'memberBindings')||jsonb_build_array(jsonb_build_object('identityId',p_identity,'uid',uid,'generation','1','version','0')));
  INSERT INTO public."HuroofMember"("namespace","roomId","firebaseIdentityId","role") VALUES(p_namespace,p_room,p_identity,'MEMBER');
 ELSE
  IF NOT FOUND OR member."revokedAt" IS NOT NULL THEN RAISE EXCEPTION 'lobby member unavailable'; END IF;
  IF intent_type='LOBBY_SET_READY' THEN
   IF (payload-ARRAY['ready']::TEXT[])<>'{}'::JSONB OR jsonb_typeof(payload->'ready') IS DISTINCT FROM 'boolean' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(lobby."state"->'members') AS m(value) WHERE m.value->>'uid'=uid AND m.value->>'role'='player' AND m.value->'active'='true'::JSONB) THEN RAISE EXCEPTION 'ready unavailable'; END IF;
   SELECT jsonb_agg(CASE WHEN v.value->>'uid'=uid THEN jsonb_set(v.value,'{ready}',payload->'ready') ELSE v.value END ORDER BY v.ordinality) INTO item FROM jsonb_array_elements(expected->'members') WITH ORDINALITY AS v(value,ordinality); expected:=jsonb_set(expected,'{members}',item);
  ELSIF intent_type='LOBBY_ASSIGN_TEAM' THEN
   IF member."role"<>'OWNER' OR (payload-ARRAY['memberUid','manualParticipantId','team']::TEXT[])<>'{}'::JSONB OR payload->>'team' NOT IN ('horizontal','vertical') OR ((payload ? 'memberUid')=(payload ? 'manualParticipantId')) THEN RAISE EXCEPTION 'team assignment unavailable'; END IF;
   target_team:=payload->>'team'; target_uid:=payload->>'memberUid'; target_id:=payload->>'manualParticipantId';
   IF target_uid IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(expected->'members') AS v(value) WHERE v.value->>'uid'=target_uid AND v.value->>'role'='player' AND v.value->'active'='true'::JSONB) THEN RAISE EXCEPTION 'team target unavailable'; END IF;
    SELECT jsonb_agg(CASE WHEN v.value->>'uid'=target_uid AND v.value->>'team' IS DISTINCT FROM target_team THEN jsonb_set(jsonb_set(v.value,'{team}',to_jsonb(target_team)),'{ready}','false'::JSONB) ELSE v.value END ORDER BY v.ordinality) INTO item FROM jsonb_array_elements(expected->'members') WITH ORDINALITY AS v(value,ordinality); expected:=jsonb_set(expected,'{members}',item);
   ELSE
    IF NOT EXISTS(SELECT 1 FROM public."HuroofParticipant" p WHERE p."namespace"=p_namespace AND p."roomId"=p_room AND p."id"=target_id AND p."memberFirebaseIdentityId" IS NULL) THEN RAISE EXCEPTION 'team target unavailable'; END IF;
    UPDATE public."HuroofParticipant" SET "team"=target_team WHERE ("namespace","roomId","id")=(p_namespace,p_room,target_id);
    SELECT jsonb_agg(CASE WHEN v.value->>'id'=target_id THEN jsonb_set(v.value,'{team}',to_jsonb(target_team)) ELSE v.value END ORDER BY v.ordinality) INTO item FROM jsonb_array_elements(expected->'room'->'manualParticipants') WITH ORDINALITY AS v(value,ordinality); expected:=jsonb_set(expected,'{room,manualParticipants}',item);
   END IF;
  ELSIF intent_type='LOBBY_ADD_MANUAL_PLAYER' THEN
   IF member."role"<>'OWNER' OR (payload-ARRAY['displayName','team']::TEXT[])<>'{}'::JSONB OR length(btrim(payload->>'displayName')) NOT BETWEEN 1 AND 48 OR payload->>'displayName' ~ '[[:cntrl:]]' OR payload->>'team' NOT IN ('horizontal','vertical') THEN RAISE EXCEPTION 'manual participant unavailable'; END IF;
   new_id:=public.eng03_03_manual_identity(p_namespace,p_room,p_identity,key); name:=payload->>'displayName'; target_team:=payload->>'team';
   SELECT count(*) INTO ord FROM public."HuroofParticipant" p WHERE p."namespace"=p_namespace AND p."roomId"=p_room;
   INSERT INTO public."HuroofParticipant"("namespace","roomId","id","displayName","team","ordinal") VALUES(p_namespace,p_room,new_id,name,target_team,ord);
   expected:=jsonb_set(expected,'{room,manualParticipants}',COALESCE(expected->'room'->'manualParticipants','[]'::JSONB)||jsonb_build_array(jsonb_build_object('id',new_id,'displayName',name,'team',target_team)));
  ELSE RAISE EXCEPTION 'lobby operation unavailable'; END IF;
 END IF;
 IF p_state IS DISTINCT FROM expected THEN RAISE EXCEPTION 'lobby transition differs'; END IF;
 raw:=convert_to(p_intent::TEXT,'UTF8'); outcome:=jsonb_build_object('roomId',p_room,'revision',p_revision+1,'replayed',false); outcome_bytes:=convert_to(outcome::TEXT,'UTF8');
 INSERT INTO public."HuroofLobbyRevision"("namespace","roomId","ownerFirebaseIdentityId","revision","roomGeneration","actorFirebaseIdentityId","requestKey","intent","intentHash","outcome","outcomeHash","state","stateHash") VALUES(p_namespace,p_room,room."ownerFirebaseIdentityId",p_revision+1,p_generation,p_identity,key,raw,encode(int4_crypto.digest(raw,'sha256'),'hex'),outcome_bytes,encode(int4_crypto.digest(outcome_bytes,'sha256'),'hex'),p_state,public.int5b_hash_json(p_state));
 RETURN outcome;
END $$;

CREATE OR REPLACE FUNCTION public.eng03_03_projection_read(p_namespace TEXT,p_identity TEXT,p_room TEXT,p_generation BIGINT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE room public."HuroofRoom"%ROWTYPE; member public."HuroofMember"%ROWTYPE; state public."HuroofCanonicalState"%ROWTYPE; projection public."HuroofProjection"%ROWTYPE; audience TEXT;
BEGIN
 PERFORM public.eng03_03_lock_room(p_namespace,p_room);
 PERFORM public.eng03_03_lock_members(p_namespace,p_room);
 SELECT * INTO room FROM public."HuroofRoom" WHERE ("namespace","id")=(p_namespace,p_room);
 SELECT * INTO member FROM public."HuroofMember" WHERE ("namespace","roomId","firebaseIdentityId")=(p_namespace,p_room,p_identity) AND "revokedAt" IS NULL;
 IF NOT FOUND OR room."generation" IS DISTINCT FROM p_generation OR NOT EXISTS(SELECT 1 FROM public."FirebaseIdentity" i JOIN public."DeploymentNamespace" n ON n."namespaceId"=p_namespace AND n."firebaseProjectId"=i."firebaseProjectId" WHERE i."id"=p_identity) THEN RAISE EXCEPTION 'projection unavailable'; END IF;
 SELECT * INTO state FROM public."HuroofCanonicalState" WHERE ("namespace","roomId")=(p_namespace,p_room);
 IF NOT FOUND THEN RAISE EXCEPTION 'projection unavailable'; END IF;
 IF jsonb_typeof(state."privateState"->'room'->'challenge')='object' AND state."privateState"->'room'->'challenge' ? 'paused' AND NOT COALESCE((jsonb_typeof(state."privateState"->'room'->'challenge'->'paused')='object' AND (state."privateState"->'room'->'challenge'->'paused'-ARRAY['at','from','deadlineAt']::TEXT[])='{}'::JSONB AND (state."privateState"->'room'->'challenge'->'paused') ?& ARRAY['at','from','deadlineAt'] AND jsonb_typeof(state."privateState"->'room'->'challenge'->'paused'->'at')='number' AND state."privateState"->'room'->'challenge'->'paused'->>'at' ~ '^(0|[1-9][0-9]{0,15})$' AND jsonb_typeof(state."privateState"->'room'->'challenge'->'paused'->'deadlineAt')='number' AND state."privateState"->'room'->'challenge'->'paused'->>'deadlineAt' ~ '^(0|[1-9][0-9]{0,15})$' AND state."privateState"->'room'->'challenge'->'paused'->>'from' IN ('countdown','observation','answer','steal_offer','steal') AND state."privateState"->'room'->'challenge'->'paused'->>'from'=state."privateState"->'room'->'challenge'->>'stage' AND state."privateState"->'room'->'challenge'->'paused'->'deadlineAt'=state."privateState"->'room'->'challenge'->'deadlineAt' AND (state."privateState"->'room'->'challenge'->'paused'->>'at')::NUMERIC<(state."privateState"->'room'->'challenge'->'paused'->>'deadlineAt')::NUMERIC),FALSE) THEN RAISE EXCEPTION 'challenge pause unavailable'; END IF;
 IF jsonb_typeof(state."privateState"->'room'->'challenge')='object' AND state."privateState"->'room'->'challenge'->'continued' IS DISTINCT FROM 'true'::JSONB AND NOT (state."privateState"->'room'->'challenge' ? 'paused') AND (state."privateState"->'room'->'challenge') ? 'deadlineAt' THEN
  IF jsonb_typeof(state."privateState"->'room'->'challenge'->'deadlineAt') IS DISTINCT FROM 'number' OR state."privateState"->'room'->'challenge'->>'deadlineAt' !~ '^(0|[1-9][0-9]{0,15})$' OR (state."privateState"->'room'->'challenge'->>'deadlineAt')::NUMERIC<=extract(epoch FROM clock_timestamp())*1000 THEN RAISE EXCEPTION 'challenge reconciliation required'; END IF;
 END IF;
 audience:=CASE WHEN member."role"='OWNER' AND room."ownerFirebaseIdentityId"=p_identity THEN 'OWNER' ELSE 'MEMBER' END;
 SELECT * INTO projection FROM public."HuroofProjection" WHERE ("namespace","roomId","audience","scope")=(p_namespace,p_room,audience,p_identity);
 IF NOT FOUND OR projection."authGeneration" IS DISTINCT FROM room."generation" OR projection."revision" IS DISTINCT FROM state."revision" OR projection."throughSequence" IS DISTINCT FROM state."sequence" OR NOT public.eng03_03_projection_safe(projection."payload",audience='OWNER') THEN RAISE EXCEPTION 'projection unavailable'; END IF;
 RETURN projection."payload";
END $$;

-- Review-only candidate: role provisioning is separate and COMMIT is intentionally absent.
